insert into public.syllabus_editions (contest_name,role_name,contest_year)
select 'Polícia Civil do Estado do Espírito Santo','Delegado de Polícia',2022
where not exists (
  select 1 from public.syllabus_editions
  where contest_name='Polícia Civil do Estado do Espírito Santo' and role_name='Delegado de Polícia' and contest_year=2022
);

-- Discipline breakdown derived directly from the prova's own section
-- headers and item content: Língua Portuguesa (1-9), Noções de Informática
-- (10-14), Estatuto dos Policiais Civis do Espírito Santo/LC nº 46 de 1994
-- (15-20) — all under "CONHECIMENTOS GERAIS"; Direito Penal (21-26), Direito
-- Processual Penal (27-35), Direito Administrativo (36-42, incluindo Lei nº
-- 8.666/1993 e Lei nº 10.520/2002), Direito Constitucional (43-51), Direitos
-- Humanos (52-56), Direito Civil (57-62), Medicina Legal (63-68),
-- Criminologia (69-75), Legislação Penal Especial (76-80) — all under
-- "CONHECIMENTOS ESPECÍFICOS".
with edition as (
  select id from public.syllabus_editions
  where contest_name='Polícia Civil do Estado do Espírito Santo' and role_name='Delegado de Polícia' and contest_year=2022
)
insert into public.syllabus_topics (edition_id,block_name,discipline,topic_order,topic_text,content_status)
select edition.id,'Prova objetiva',d.discipline,1,d.topic_text,'current'
from edition cross join (values
  ('Língua Portuguesa','Compreensão e interpretação de texto, coesão e coerência, pontuação, morfossintaxe e reescrita de segmentos, a partir do texto CG1A1-I sobre violência doméstica no contexto da pandemia de covid-19.'),
  ('Noções de Informática','Navegador Google Chrome, compactação/extração de arquivos no Windows 10, tipos de memória (ROM), fórmulas do MS Excel 2016 e segurança na Internet (phishing, anexos maliciosos).'),
  ('Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)','Hierarquia e disciplina, nomeação para função de delegado-chefe, sanções administrativas disciplinares, suspensão preventiva, revisão do processo administrativo disciplinar e prerrogativas dos servidores policiais civis.'),
  ('Direito Penal','Furto qualificado e causas de aumento, crimes contra a dignidade sexual, extinção da punibilidade, parte geral do Código Penal (erro sobre a pessoa, perdão, suspensão condicional da pena) e crimes contra o patrimônio.'),
  ('Direito Processual Penal','Inquérito policial, indiciamento, atribuição territorial e federalização, prisão em flagrante e uso de algemas, medidas cautelares diversas da prisão e fiança, investigações policiais (reconhecimento de pessoa, reconstituição), busca e apreensão domiciliar.'),
  ('Direito Administrativo','Descentralização e desconcentração, conceito e espécies de ato administrativo, improbidade administrativa (Lei nº 8.429/1992), poder de polícia, licitação na modalidade pregão (Lei nº 10.520/2002) e garantias em contratos administrativos (Lei nº 8.666/1993).'),
  ('Direito Constitucional','Direitos e garantias fundamentais, objetivos fundamentais da República, direitos sociais, intervenção do Estado no Município, estado de defesa, criação e desmembramento de Municípios e medidas provisórias.'),
  ('Direitos Humanos','Código de Conduta para os Funcionários Responsáveis pela Aplicação da Lei (Resolução ONU nº 34/169), Declaração Universal dos Direitos Humanos, Lei nº 13.060/2014 (uso de instrumentos de menor potencial ofensivo), Convenção contra a Tortura (Decreto nº 40/1991) e dever de investigar segundo a Corte Interamericana de Direitos Humanos.'),
  ('Direito Civil','Convenção Americana de Direitos Humanos e caso Favela Nova Brasília, prescrição da pretensão de reparação civil, obrigações alternativas, negócios jurídicos, cláusula resolutiva expressa em compra e venda e nulidade do negócio jurídico.'),
  ('Medicina Legal','Ramos da medicina legal, corpo de delito e perícia, documentos médico-legais, identificação civil e datiloscopia (sistema de Vucetich) e lesões por projétil de arma de fogo.'),
  ('Criminologia','Escola ecológica, prevenção primária, interdisciplinaridade da criminologia, visão positivista/correcionalista do delinquente e função básica da criminologia.'),
  ('Legislação Penal Especial','Lei nº 11.340/2006 (Maria da Penha), Lei nº 11.343/2006 (tráfico e associação para o tráfico), Estatuto do Desarmamento, Lei nº 13.869/2019 (abuso de autoridade), Lei nº 9.613/1998 (lavagem de dinheiro) e Estatuto da Criança e do Adolescente.')
) d(discipline,topic_text)
on conflict (edition_id,discipline,topic_order) do update set topic_text=excluded.topic_text;

with imported(exam_year,item_number,subject,question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,context_review_required,review_note) as (values
(2022,1,$q$Língua Portuguesa$q$,$q$Com base nas informações veiculadas no texto CG1A1-I, no que diz respeito ao contexto da pandemia de covid-19 e à violência contra a mulher, é correto afirmar que A as instituições policiais observaram ampliação dos tipos de crime praticados contra a mulher durante a pandemia. B as mulheres de classe social economicamente desfavorecida foram as principais vítimas de violência doméstica durante a pandemia. C a facilitação do acesso aos meios de denúncia de violência doméstica durante a pandemia acarretou a diminuição desse tipo de crime em curto período de tempo. D o número de mulheres mortas em razão da violência doméstica aumentou durante a pandemia. E o aumento da incidência de violência contra a mulher durante a pandemia não se restringiu ao território brasileiro.$q$,$q$Com base nas informações veiculadas no texto CG1A1-I, no que diz respeito ao contexto da pandemia de covid-19 e à violência contra a mulher, é correto afirmar que A as instituições policiais observaram ampliação dos tipos de crime praticados contra a mulher durante a pandemia. B as mulheres de classe social economicamente desfavorecida foram as principais vítimas de violência doméstica durante a pandemia. C a facilitação do acesso aos meios de denúncia de violência doméstica durante a pandemia acarretou a diminuição desse tipo de crime em curto período de tempo. D o número de mulheres mortas em razão da violência doméstica aumentou durante a pandemia. E o aumento da incidência de violência contra a mulher durante a pandemia não se restringiu ao território brasileiro.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,2,$q$Língua Portuguesa$q$,$q$Assinale a opção correta conforme as ideias veiculadas no último parágrafo do texto CG1A1-I. A O sistema de registro online de casos de violência contra a mulher implantado nos estados brasileiros baseou-se em um modelo adotado em outros países. B Antes da pandemia de covid-19, em algumas unidades da Federação, não havia a possibilidade de denúncia online de casos de violência contra a mulher. C As campanhas de denúncia à violência doméstica feitas em farmácias e supermercados alcançaram quase a totalidade dos estados e municípios brasileiros. D A queda nos registros de casos de violência contra a mulher durante a pandemia de covid-19 justifica-se pelas ameaças de retaliação feitas pelos agressores contra suas vítimas. E O boletim de ocorrência online foi adotado no contexto da pandemia de covid-19, inicialmente, para atender exclusivamente as denúncias de casos de violência contra a mulher.$q$,$q$Assinale a opção correta conforme as ideias veiculadas no último parágrafo do texto CG1A1-I. A O sistema de registro online de casos de violência contra a mulher implantado nos estados brasileiros baseou-se em um modelo adotado em outros países. B Antes da pandemia de covid-19, em algumas unidades da Federação, não havia a possibilidade de denúncia online de casos de violência contra a mulher. C As campanhas de denúncia à violência doméstica feitas em farmácias e supermercados alcançaram quase a totalidade dos estados e municípios brasileiros. D A queda nos registros de casos de violência contra a mulher durante a pandemia de covid-19 justifica-se pelas ameaças de retaliação feitas pelos agressores contra suas vítimas. E O boletim de ocorrência online foi adotado no contexto da pandemia de covid-19, inicialmente, para atender exclusivamente as denúncias de casos de violência contra a mulher.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,3,$q$Língua Portuguesa$q$,$q$Considerando a pontuação empregada no primeiro período do segundo parágrafo do texto CG1A1-I, assinale a opção correta. A A correção gramatical do texto seria mantida caso fosse inserida uma vírgula logo após a expressão “assim como”. B A inserção de vírgula logo após “Anuário Brasileiro de Segurança Pública” manteria a correção gramatical do texto. C A eliminação da vírgula imediatamente seguinte à palavra “mulher” manteria a correção gramatical do texto. D A substituição do sinal de dois-pontos por ponto final prejudicaria a correção gramatical do texto, ainda que feito o devido ajuste de letra inicial minúscula e maiúscula. E A substituição da vírgula empregada após “190” por ponto final prejudicaria a correção gramatical do texto, ainda que feito o devido ajuste de letra inicial minúscula e maiúscula.$q$,$q$Considerando a pontuação empregada no primeiro período do segundo parágrafo do texto CG1A1-I, assinale a opção correta. A A correção gramatical do texto seria mantida caso fosse inserida uma vírgula logo após a expressão “assim como”. B A inserção de vírgula logo após “Anuário Brasileiro de Segurança Pública” manteria a correção gramatical do texto. C A eliminação da vírgula imediatamente seguinte à palavra “mulher” manteria a correção gramatical do texto. D A substituição do sinal de dois-pontos por ponto final prejudicaria a correção gramatical do texto, ainda que feito o devido ajuste de letra inicial minúscula e maiúscula. E A substituição da vírgula empregada após “190” por ponto final prejudicaria a correção gramatical do texto, ainda que feito o devido ajuste de letra inicial minúscula e maiúscula.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,4,$q$Língua Portuguesa$q$,$q$No primeiro período do segundo parágrafo do texto CG1A1-I, a expressão “assim como” estabelece uma noção de A conclusão. B proporcionalidade. C contraste. D adição. E explicação.$q$,$q$No primeiro período do segundo parágrafo do texto CG1A1-I, a expressão “assim como” estabelece uma noção de A conclusão. B proporcionalidade. C contraste. D adição. E explicação.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,5,$q$Língua Portuguesa$q$,$q$Conforme as ideias do terceiro parágrafo do texto CG1A1-I, a crise econômica vivenciada no Brasil foi intensificada devido A ao contexto da pandemia de covid-19. B à retomada parcial das atividades rotineiras em 2021. C aos índices de transmissão da covid-19 em 2021. D às estatísticas criminais de violência contra as mulheres nos anos de 2020 e 2021. E à falta de políticas públicas para prevenir a covid-19.$q$,$q$Conforme as ideias do terceiro parágrafo do texto CG1A1-I, a crise econômica vivenciada no Brasil foi intensificada devido A ao contexto da pandemia de covid-19. B à retomada parcial das atividades rotineiras em 2021. C aos índices de transmissão da covid-19 em 2021. D às estatísticas criminais de violência contra as mulheres nos anos de 2020 e 2021. E à falta de políticas públicas para prevenir a covid-19.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,6,$q$Língua Portuguesa$q$,$q$Cada uma das opções a seguir apresenta uma proposta de reescrita para o segmento “nos ajuda a pensar”, no segundo período do terceiro parágrafo do texto CG1A1-I. Assinale a opção em que a proposta apresentada mantém a coerência, o nível de formalidade e a correção gramatical do texto. A ajuda à nós pensarmos B ajuda à gente pensar C ajuda a gente pensarmos D ajuda-nos a pensar E ajuda nos à pensar$q$,$q$Cada uma das opções a seguir apresenta uma proposta de reescrita para o segmento “nos ajuda a pensar”, no segundo período do terceiro parágrafo do texto CG1A1-I. Assinale a opção em que a proposta apresentada mantém a coerência, o nível de formalidade e a correção gramatical do texto. A ajuda à nós pensarmos B ajuda à gente pensar C ajuda a gente pensarmos D ajuda-nos a pensar E ajuda nos à pensar$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,7,$q$Língua Portuguesa$q$,$q$Estariam preservados os sentidos e a correção gramatical do primeiro período do texto CG1A1-I caso se deslocasse o vocábulo “ainda” para imediatamente depois de A “2020”. B “covid-19”. C “mulheres”. D “violência”. E “vulneráveis”.$q$,$q$Estariam preservados os sentidos e a correção gramatical do primeiro período do texto CG1A1-I caso se deslocasse o vocábulo “ainda” para imediatamente depois de A “2020”. B “covid-19”. C “mulheres”. D “violência”. E “vulneráveis”.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,8,$q$Língua Portuguesa$q$,$q$No texto CG1A1-I, o vocábulo “ampliação” (segundo período do quarto parágrafo) veicula o mesmo sentido da palavra A abrangência. B criação. C autorização. D aumento. E mudança.$q$,$q$No texto CG1A1-I, o vocábulo “ampliação” (segundo período do quarto parágrafo) veicula o mesmo sentido da palavra A abrangência. B criação. C autorização. D aumento. E mudança.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,9,$q$Língua Portuguesa$q$,$q$No primeiro período do quarto parágrafo, a oração “embora tenha ocorrido queda nos registros” expressa circunstância de A causa. B conformidade. C condição. D concessão. E consequência.$q$,$q$No primeiro período do quarto parágrafo, a oração “embora tenha ocorrido queda nos registros” expressa circunstância de A causa. B conformidade. C condição. D concessão. E consequência.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,10,$q$Noções de Informática$q$,$q$Na versão mais atual do navegador Google Chrome, ao se digitar, na barra de endereço, a URL https://pc.es.gov.br, correspondente ao site da Polícia Civil do Estado do Espírito Santo, e se clicar no botão , localizado no canto superior direito da tela, será A mostrado o site da Polícia Civil do Estado do Espírito Santo no formato texto, ou seja, sem a exibição de imagens. B exibido o site da Polícia Civil do Estado do Espírito Santo em uma janela protegida (janela anônima). C mostrado o painel lateral. D duplicada a janela do navegador. E mostrado apenas o histórico de acessos ao site da Polícia Civil do Estado do Espírito Santo, ordenado pela data dos acessos.$q$,$q$Na versão mais atual do navegador Google Chrome, ao se digitar, na barra de endereço, a URL https://pc.es.gov.br, correspondente ao site da Polícia Civil do Estado do Espírito Santo, e se clicar no botão , localizado no canto superior direito da tela, será A mostrado o site da Polícia Civil do Estado do Espírito Santo no formato texto, ou seja, sem a exibição de imagens. B exibido o site da Polícia Civil do Estado do Espírito Santo em uma janela protegida (janela anônima). C mostrado o painel lateral. D duplicada a janela do navegador. E mostrado apenas o histórico de acessos ao site da Polícia Civil do Estado do Espírito Santo, ordenado pela data dos acessos.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,11,$q$Noções de Informática$q$,$q$Um delegado da Polícia Civil do Estado do Espírito Santo recebeu email do diretor da Academia de Polícia, com os arquivos aprovados.rar, desligados.rar e subjudices.rar, e fez download desses arquivos para a unidade C:\ de seu computador de trabalho. Posteriormente, utilizando o Explorador de Arquivos do sistema operacional Windows 10, esse delegado de polícia selecionou os três arquivos, clicou o botão direito do mouse sobre eles e selecionou a opção . Nessa situação hipotética, A todos os arquivos serão descompactados diretamente para a raiz do sistema operacional Windows 10, ou seja, para a unidade C:\. B cada arquivo será extraído para pastas específicas, que serão criadas, no momento da extração, dentro da unidade C:\. C por padrão, os arquivos serão extraídos e enviados, automaticamente, para a Área de Trabalho do Windows 10. D os arquivos serão extraídos e enviados, automaticamente, para a pasta Documentos. E uma caixa de diálogo será exibida, fornecendo ao usuário a possibilidade de informar o caminho de destino, além de diversas outras opções de extração.$q$,$q$Um delegado da Polícia Civil do Estado do Espírito Santo recebeu email do diretor da Academia de Polícia, com os arquivos aprovados.rar, desligados.rar e subjudices.rar, e fez download desses arquivos para a unidade C:\ de seu computador de trabalho. Posteriormente, utilizando o Explorador de Arquivos do sistema operacional Windows 10, esse delegado de polícia selecionou os três arquivos, clicou o botão direito do mouse sobre eles e selecionou a opção . Nessa situação hipotética, A todos os arquivos serão descompactados diretamente para a raiz do sistema operacional Windows 10, ou seja, para a unidade C:\. B cada arquivo será extraído para pastas específicas, que serão criadas, no momento da extração, dentro da unidade C:\. C por padrão, os arquivos serão extraídos e enviados, automaticamente, para a Área de Trabalho do Windows 10. D os arquivos serão extraídos e enviados, automaticamente, para a pasta Documentos. E uma caixa de diálogo será exibida, fornecendo ao usuário a possibilidade de informar o caminho de destino, além de diversas outras opções de extração.$q$,'E',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,12,$q$Noções de Informática$q$,$q$Assinale a opção que indica o tipo de memória que é integrada à placa-mãe do computador e na qual as informações apenas podem ser acessadas, e não alteradas, por serem gravadas pelo fabricante uma única vez. A ROM B DRAM C cache D SSD E virtual$q$,$q$Assinale a opção que indica o tipo de memória que é integrada à placa-mãe do computador e na qual as informações apenas podem ser acessadas, e não alteradas, por serem gravadas pelo fabricante uma única vez. A ROM B DRAM C cache D SSD E virtual$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,13,$q$Noções de Informática$q$,$q$Considere que, na planilha anterior, editada no programa MS Excel 2016, a célula selecionada esteja formatada como número, sem casas decimais, e que deva ser inserida na célula C3 uma fórmula para mostrar, automaticamente, a quantidade de dias na prisão, com base na contagem de prazo definida no Código de Processo Penal. A partir dessas informações, assinale a opção que apresenta corretamente a fórmula a ser inserida na célula C3. A =(B3-HOJE();"D")+1 B =(DATADIF(B3; HOJE();"D"))+1 C =(COUNT(HOJE();B3;"D"))+1 D =(AGORA(B3; HOJE();"D"))+1 E =(DIAS(B3; HOJE();"D"))+1$q$,$q$Considere que, na planilha anterior, editada no programa MS Excel 2016, a célula selecionada esteja formatada como número, sem casas decimais, e que deva ser inserida na célula C3 uma fórmula para mostrar, automaticamente, a quantidade de dias na prisão, com base na contagem de prazo definida no Código de Processo Penal. A partir dessas informações, assinale a opção que apresenta corretamente a fórmula a ser inserida na célula C3. A =(B3-HOJE();"D")+1 B =(DATADIF(B3; HOJE();"D"))+1 C =(COUNT(HOJE();B3;"D"))+1 D =(AGORA(B3; HOJE();"D"))+1 E =(DIAS(B3; HOJE();"D"))+1$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,14,$q$Noções de Informática$q$,$q$Julgue os itens a seguir, em relação a segurança na Internet. I Emails em que se solicitem dados pessoais do usuário não são suspeitos se tiverem sido enviados por instituições bancárias ou pela Receita Federal do Brasil, por exemplo, pois, nesses casos, os remetentes são órgãos confiáveis e totalmente seguros. II Manter o sistema operacional e o antivírus atualizados ajuda o usuário a se prevenir de phishing. III Os anexos de emails são confiáveis, pois os provedores possuem tecnologia avançada que impede a disseminação de pragas virtuais em anexos, logo o usuário pode baixar e executar quaisquer arquivos recebidos por email, sem nenhum tipo de risco, ainda que possuam as extensões .exe e .bat, por exemplo. Assinale a opção correta. A Apenas o item II está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens I e III estão certos. E Todos os itens estão certos.$q$,$q$Julgue os itens a seguir, em relação a segurança na Internet. I Emails em que se solicitem dados pessoais do usuário não são suspeitos se tiverem sido enviados por instituições bancárias ou pela Receita Federal do Brasil, por exemplo, pois, nesses casos, os remetentes são órgãos confiáveis e totalmente seguros. II Manter o sistema operacional e o antivírus atualizados ajuda o usuário a se prevenir de phishing. III Os anexos de emails são confiáveis, pois os provedores possuem tecnologia avançada que impede a disseminação de pragas virtuais em anexos, logo o usuário pode baixar e executar quaisquer arquivos recebidos por email, sem nenhum tipo de risco, ainda que possuam as extensões .exe e .bat, por exemplo. Assinale a opção correta. A Apenas o item II está certo. B Apenas o item III está certo. C Apenas os itens I e II estão certos. D Apenas os itens I e III estão certos. E Todos os itens estão certos.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,15,$q$Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)$q$,$q$Sabendo que a função policial se fundamenta na hierarquia e na disciplina, assinale a opção correta, à luz do Estatuto dos Policiais Civis do Estado do Espírito Santo. A Havendo igualdade de padrões funcionais entre servidores do mesmo cargo, prevalecerá a hierarquia do mais antigo. B A hierarquia do cargo, no caso do delegado de polícia, prevalece sobre a hierarquia da função. C Os servidores policiais especializados, nos serviços em equipe prestados em unidade policial do interior do estado, terão precedência hierárquica sobre os demais. D A hierarquia da função tem por base a posição das unidades administrativas na estrutura organizacional da Polícia Civil em relação ao governador do estado. E A disciplina policial civil baseia-se, precipuamente, na ordenação das autoridades em diferentes níveis e de acordo com o cargo em exercício.$q$,$q$Sabendo que a função policial se fundamenta na hierarquia e na disciplina, assinale a opção correta, à luz do Estatuto dos Policiais Civis do Estado do Espírito Santo. A Havendo igualdade de padrões funcionais entre servidores do mesmo cargo, prevalecerá a hierarquia do mais antigo. B A hierarquia do cargo, no caso do delegado de polícia, prevalece sobre a hierarquia da função. C Os servidores policiais especializados, nos serviços em equipe prestados em unidade policial do interior do estado, terão precedência hierárquica sobre os demais. D A hierarquia da função tem por base a posição das unidades administrativas na estrutura organizacional da Polícia Civil em relação ao governador do estado. E A disciplina policial civil baseia-se, precipuamente, na ordenação das autoridades em diferentes níveis e de acordo com o cargo em exercício.$q$,'A',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,16,$q$Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)$q$,$q$Delegado da Polícia Civil do Estado do Espírito Santo, ao terminar satisfatoriamente o estágio probatório, foi indicado pelo governador para assumir a função de delegado-chefe da instituição. Nessa situação hipotética, conforme a Constituição do Estado do Espírito Santo, a nomeação será A inviável, porque a escolha de nome para a função de delegado-chefe deverá se dar a partir de lista tríplice apresentada pelo órgão de representação da categoria. B viável, porque os atos de designação para as funções privativas da carreira de delegado de polícia são de competência exclusiva e de livre escolha do governador do estado, sem impedimentos quanto à classe funcional do servidor. C inviável, porque a escolha de nome para a função de delegado-chefe deverá se dar a partir de lista tríplice apresentada pelo Conselho de Polícia Civil. D inviável, porque a escolha de nome para a função de delegado-chefe deverá se limitar aos integrantes da última classe da carreira de delegado de polícia. E viável, porque a única exigência legal para a nomeação à função de delegado-chefe é a estabilidade do servidor no cargo de delegado de polícia.$q$,$q$Delegado da Polícia Civil do Estado do Espírito Santo, ao terminar satisfatoriamente o estágio probatório, foi indicado pelo governador para assumir a função de delegado-chefe da instituição. Nessa situação hipotética, conforme a Constituição do Estado do Espírito Santo, a nomeação será A inviável, porque a escolha de nome para a função de delegado-chefe deverá se dar a partir de lista tríplice apresentada pelo órgão de representação da categoria. B viável, porque os atos de designação para as funções privativas da carreira de delegado de polícia são de competência exclusiva e de livre escolha do governador do estado, sem impedimentos quanto à classe funcional do servidor. C inviável, porque a escolha de nome para a função de delegado-chefe deverá se dar a partir de lista tríplice apresentada pelo Conselho de Polícia Civil. D inviável, porque a escolha de nome para a função de delegado-chefe deverá se limitar aos integrantes da última classe da carreira de delegado de polícia. E viável, porque a única exigência legal para a nomeação à função de delegado-chefe é a estabilidade do servidor no cargo de delegado de polícia.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,17,$q$Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)$q$,$q$Um delegado da Polícia Civil do Estado do Espírito Santo, não reincidente em transgressões disciplinares, divulgou, indevidamente, em rede social na Internet, fatos de repercussão ocorridos na repartição policial onde trabalha, sem conhecimento ou autorização da sua chefia imediata. Nessa situação hipotética, após o devido processo legal, será cabível a aplicação da sanção administrativa de A alteração compulsória de localização. B advertência. C repreensão. D suspensão de até trinta dias. E suspensão de até sessenta dias.$q$,$q$Um delegado da Polícia Civil do Estado do Espírito Santo, não reincidente em transgressões disciplinares, divulgou, indevidamente, em rede social na Internet, fatos de repercussão ocorridos na repartição policial onde trabalha, sem conhecimento ou autorização da sua chefia imediata. Nessa situação hipotética, após o devido processo legal, será cabível a aplicação da sanção administrativa de A alteração compulsória de localização. B advertência. C repreensão. D suspensão de até trinta dias. E suspensão de até sessenta dias.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,18,$q$Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)$q$,$q$Um delegado da Polícia Civil do Estado do Espírito Santo reincidente em faltas leves praticou nova transgressão disciplinar leve, estando, assim, sujeito à penalidade de suspensão. No âmbito do devido procedimento disciplinar nessa situação hipotética, a suspensão preventiva desse servidor A não poderá acontecer, por ser instituto aplicável somente às transgressões penalizadas com demissão. B é cabível, desde que observados os requisitos legais pertinentes. C não poderá acontecer, uma vez que se trata da prática de apenas faltas leves, embora reiteradas. D é cabível, podendo estender-se desde a instauração do procedimento disciplinar até a decisão final da autoridade julgadora, com prejuízo da remuneração do servidor por até noventa dias. E é cabível, podendo estender-se desde a instauração do procedimento disciplinar até a decisão final da autoridade julgadora, sem prejuízo da remuneração do servidor.$q$,$q$Um delegado da Polícia Civil do Estado do Espírito Santo reincidente em faltas leves praticou nova transgressão disciplinar leve, estando, assim, sujeito à penalidade de suspensão. No âmbito do devido procedimento disciplinar nessa situação hipotética, a suspensão preventiva desse servidor A não poderá acontecer, por ser instituto aplicável somente às transgressões penalizadas com demissão. B é cabível, desde que observados os requisitos legais pertinentes. C não poderá acontecer, uma vez que se trata da prática de apenas faltas leves, embora reiteradas. D é cabível, podendo estender-se desde a instauração do procedimento disciplinar até a decisão final da autoridade julgadora, com prejuízo da remuneração do servidor por até noventa dias. E é cabível, podendo estender-se desde a instauração do procedimento disciplinar até a decisão final da autoridade julgadora, sem prejuízo da remuneração do servidor.$q$,'B',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,19,$q$Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)$q$,$q$No que concerne à revisão do processo administrativo disciplinar, assinale a opção correta, de acordo com o Estatuto dos Policiais Civis do Estado do Espírito Santo. A A revisão do processo administrativo disciplinar é cabível somente nos casos de aplicação da pena de demissão ou cassação de aposentadoria. B O prazo máximo para requerer a revisão do processo administrativo disciplinar é de dois anos. C A revisão do processo administrativo disciplinar pode ser postulada a qualquer tempo e direcionada à aplicação de qualquer penalidade administrativa disciplinar. D O julgamento do pedido de revisão do processo administrativo disciplinar cabe exclusivamente ao chefe do Poder Executivo estadual. E A revisão do processo administrativo disciplinar é direito intransferível, não sendo possível a intervenção de sucessor no caso de morte ou ausência do interessado.$q$,$q$No que concerne à revisão do processo administrativo disciplinar, assinale a opção correta, de acordo com o Estatuto dos Policiais Civis do Estado do Espírito Santo. A A revisão do processo administrativo disciplinar é cabível somente nos casos de aplicação da pena de demissão ou cassação de aposentadoria. B O prazo máximo para requerer a revisão do processo administrativo disciplinar é de dois anos. C A revisão do processo administrativo disciplinar pode ser postulada a qualquer tempo e direcionada à aplicação de qualquer penalidade administrativa disciplinar. D O julgamento do pedido de revisão do processo administrativo disciplinar cabe exclusivamente ao chefe do Poder Executivo estadual. E A revisão do processo administrativo disciplinar é direito intransferível, não sendo possível a intervenção de sucessor no caso de morte ou ausência do interessado.$q$,'C',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,20,$q$Estatuto dos Policiais Civis do Espírito Santo (LC nº 46/1994)$q$,$q$Nos termos do Estatuto dos Policiais Civis do Estado do Espírito Santo, os servidores policiais civis desse estado gozam da prerrogativa de A portar arma de fogo, mesmo na inatividade, desde que tenham autorização do órgão competente. B obter assistência médico-hospitalar às expensas do estado, em quaisquer circunstâncias, enquanto estiverem na ativa. C fazer uso de insígnia e identificação funcional mesmo após a aposentação. D receber assistência jurídica estatal, quando submetidos a processo judicial em razão do exercício do cargo. E desempenhar quaisquer cargos e funções no âmbito dos órgãos de segurança pública estaduais, independentemente da sua condição hierárquica.$q$,$q$Nos termos do Estatuto dos Policiais Civis do Estado do Espírito Santo, os servidores policiais civis desse estado gozam da prerrogativa de A portar arma de fogo, mesmo na inatividade, desde que tenham autorização do órgão competente. B obter assistência médico-hospitalar às expensas do estado, em quaisquer circunstâncias, enquanto estiverem na ativa. C fazer uso de insígnia e identificação funcional mesmo após a aposentação. D receber assistência jurídica estatal, quando submetidos a processo judicial em razão do exercício do cargo. E desempenhar quaisquer cargos e funções no âmbito dos órgãos de segurança pública estaduais, independentemente da sua condição hierárquica.$q$,'D',1,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,21,$q$Direito Penal$q$,$q$Paulo foi surpreendido em uma abordagem policial enquanto consumia um cigarro de maconha e portava outro para consumir em momento posterior. Com o fim de evitar sua condução à delegacia, Paulo ofereceu seu aparelho celular de última geração aos policiais. Nessa situação hipotética, de acordo com o entendimento dos tribunais superiores, Paulo A deve ser autuado em flagrante delito pelo crime de corrupção passiva por tentar impedir a atuação da polícia. B cometeu crime de corrupção ativa ao oferecer vantagem aos policiais na tentativa de que não o levassem à delegacia pela conduta de posse de drogas ilícitas. C pode ser acusado pelo crime de corrupção ativa na modalidade tentada, caso os policiais não tenham aceitado a oferta. D cometeu o crime de favorecimento pessoal, previsto no Código Penal, ao oferecer o aparelho celular aos policiais. E não deve ser autuado por nenhum crime, em razão de a conduta de uso de entorpecentes ter sido descriminalizada.$q$,$q$Paulo foi surpreendido em uma abordagem policial enquanto consumia um cigarro de maconha e portava outro para consumir em momento posterior. Com o fim de evitar sua condução à delegacia, Paulo ofereceu seu aparelho celular de última geração aos policiais. Nessa situação hipotética, de acordo com o entendimento dos tribunais superiores, Paulo A deve ser autuado em flagrante delito pelo crime de corrupção passiva por tentar impedir a atuação da polícia. B cometeu crime de corrupção ativa ao oferecer vantagem aos policiais na tentativa de que não o levassem à delegacia pela conduta de posse de drogas ilícitas. C pode ser acusado pelo crime de corrupção ativa na modalidade tentada, caso os policiais não tenham aceitado a oferta. D cometeu o crime de favorecimento pessoal, previsto no Código Penal, ao oferecer o aparelho celular aos policiais. E não deve ser autuado por nenhum crime, em razão de a conduta de uso de entorpecentes ter sido descriminalizada.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,22,$q$Direito Penal$q$,$q$De acordo com o artigo 83 do Código Penal, o juiz poderá conceder livramento condicional ao condenado a pena privativa de liberdade igual ou superior a dois anos, desde que o condenado A não seja reincidente. B não tenha cometido falta grave nos últimos dois anos. C tenha reparado o dano causado pela infração, salvo efetiva impossibilidade de fazê-lo. D tenha cumprido mais de 2/5 da pena, nos casos de condenação por crime hediondo. E tenha cumprido mais de 1/6 da pena, se não for reincidente em crime doloso, e mais da metade da pena, se for reincidente em crime doloso.$q$,$q$De acordo com o artigo 83 do Código Penal, o juiz poderá conceder livramento condicional ao condenado a pena privativa de liberdade igual ou superior a dois anos, desde que o condenado A não seja reincidente. B não tenha cometido falta grave nos últimos dois anos. C tenha reparado o dano causado pela infração, salvo efetiva impossibilidade de fazê-lo. D tenha cumprido mais de 2/5 da pena, nos casos de condenação por crime hediondo. E tenha cumprido mais de 1/6 da pena, se não for reincidente em crime doloso, e mais da metade da pena, se for reincidente em crime doloso.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,23,$q$Direito Penal$q$,$q$A respeito da aplicação da pena, levando em consideração o entendimento do Superior Tribunal de Justiça e os dispositivos do Código Penal, assinale a opção correta. A Condenações criminais transitadas em julgado, ainda que consideradas para caracterizar a reincidência, podem ser valoradas, na primeira fase da dosimetria da pena, a título de antecedentes criminais. B Na fixação da pena de multa, o juiz deve atender, exclusivamente, à situação econômica do réu. C A pena privativa de liberdade não superior a seis meses pode ser substituída por multa. D Verifica-se a reincidência quando o agente comete novo crime depois da sentença, ainda que recorrível, a qual, no país ou no estrangeiro, o tenha condenado por crime anterior. E Sobrevindo condenação por fato posterior ao trânsito em julgado da sentença, far-se-á nova unificação, desprezandose, para esse fim, o período de pena já cumprido.$q$,$q$A respeito da aplicação da pena, levando em consideração o entendimento do Superior Tribunal de Justiça e os dispositivos do Código Penal, assinale a opção correta. A Condenações criminais transitadas em julgado, ainda que consideradas para caracterizar a reincidência, podem ser valoradas, na primeira fase da dosimetria da pena, a título de antecedentes criminais. B Na fixação da pena de multa, o juiz deve atender, exclusivamente, à situação econômica do réu. C A pena privativa de liberdade não superior a seis meses pode ser substituída por multa. D Verifica-se a reincidência quando o agente comete novo crime depois da sentença, ainda que recorrível, a qual, no país ou no estrangeiro, o tenha condenado por crime anterior. E Sobrevindo condenação por fato posterior ao trânsito em julgado da sentença, far-se-á nova unificação, desprezandose, para esse fim, o período de pena já cumprido.$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (729_PC_ES_DELEGADO_GABARITOS); não é exibido aos estudantes.$q$),
(2022,24,$q$Direito Penal$q$,$q$Durante o período de repouso noturno, Pedro cometeu o crime de furto de um veículo que estava guardado na garagem da casa da família Silva. No decorrer das investigações, foi possível constatar que Pedro era primário e que, pela análise das imagens das câmeras de segurança instaladas no jardim da residência, havia movimentação dentro da casa, ou seja, membros da família Silva estavam acordados dentro da residência. A partir dessa situação hipotética, assinale a opção correta. A É irrelevante o fato de as vítimas estarem ou não dormindo no momento do crime, bastando que o furto tenha sido praticado à noite, durante o repouso noturno, para caracterizar a causa de aumento de pena. B Apesar de o crime ter sido cometido durante o horário de repouso noturno, não deve ser aplicada a causa de aumento de pena, pois havia pessoas acordadas dentro da residência. C Ainda que Pedro tenha rompido obstáculo para adentrar a casa, o furto não poderá ser considerado qualificado, pois o referido fato é elementar do crime de furto. D O fato de Pedro ser primário é, por si só, suficiente para que o juiz substitua a pena de reclusão pela de detenção ou aplique apenas a pena de multa. E Caso Pedro tivesse se utilizado de escalada para cometer o crime, tal qualificadora só poderia ser reconhecida mediante prova pericial.$q$,$q$Durante o período de repouso noturno, Pedro cometeu o crime de furto de um veículo que estava guardado na garagem da casa da família Silva. No decorrer das investigações, foi possível constatar que Pedro era primário e que, pela análise das imagens das câmeras de segurança instaladas no jardim da residência, havia movimentação dentro da casa, ou seja, membros da família Silva estavam acordados dentro da residência. A partir dessa situação hipotética, assinale a opção correta. A É irrelevante o fato de as vítimas estarem ou não dormindo no momento do crime, bastando que o furto tenha sido praticado à noite, durante o repouso noturno, para caracterizar a causa de aumento de pena. B Apesar de o crime ter sido cometido durante o horário de repouso noturno, não deve ser aplicada a causa de aumento de pena, pois havia pessoas acordadas dentro da residência. C Ainda que Pedro tenha rompido obstáculo para adentrar a casa, o furto não poderá ser considerado qualificado, pois o referido fato é elementar do crime de furto. D O fato de Pedro ser primário é, por si só, suficiente para que o juiz substitua a pena de reclusão pela de detenção ou aplique apenas a pena de multa. E Caso Pedro tivesse se utilizado de escalada para cometer o crime, tal qualificadora só poderia ser reconhecida mediante prova pericial.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,25,$q$Direito Penal$q$,$q$A dignidade sexual é tema que tem sido socialmente debatido com maior seriedade nas últimas décadas e que merece atenção da sociedade. A discussão em torno do assunto tem gerado reação legislativa positiva e atenção dos tribunais. Acerca desse tema, considerando os dispositivos do Código Penal e a jurisprudência do Superior Tribunal de Justiça, assinale a opção correta. A A importunação sexual, que consiste no ato de constranger alguém à prática de atos libidinosos, passou a ser um tipo penal diferente do estupro por força da Lei n.º 13.718/2018. B A exploração sexual constitui elemento normativo do crime de casa de prostituição, não bastando a conduta consistente na manutenção de casa para fins libidinosos. C Para os crimes praticados contra a dignidade sexual, não há previsão de causa de aumento de pena. D Constitui crime de rufianismo a indução à prostituição ou a outra forma de exploração sexual. E O crime de estupro, previsto no artigo 215 do Código Penal, processa-se mediante representação.$q$,$q$A dignidade sexual é tema que tem sido socialmente debatido com maior seriedade nas últimas décadas e que merece atenção da sociedade. A discussão em torno do assunto tem gerado reação legislativa positiva e atenção dos tribunais. Acerca desse tema, considerando os dispositivos do Código Penal e a jurisprudência do Superior Tribunal de Justiça, assinale a opção correta. A A importunação sexual, que consiste no ato de constranger alguém à prática de atos libidinosos, passou a ser um tipo penal diferente do estupro por força da Lei n.º 13.718/2018. B A exploração sexual constitui elemento normativo do crime de casa de prostituição, não bastando a conduta consistente na manutenção de casa para fins libidinosos. C Para os crimes praticados contra a dignidade sexual, não há previsão de causa de aumento de pena. D Constitui crime de rufianismo a indução à prostituição ou a outra forma de exploração sexual. E O crime de estupro, previsto no artigo 215 do Código Penal, processa-se mediante representação.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,26,$q$Direito Penal$q$,$q$A respeito da extinção da punibilidade, assinale a opção correta à luz do disposto no Código Penal e da jurisprudência dos tribunais superiores. A A retratação do agente não extingue a punibilidade. B Só há efetiva extinção da punibilidade quando cumprida a pena privativa de liberdade e adimplido o pagamento da pena pecuniária, ainda que o condenado comprove hipossuficiência. C Não corre prescrição antes do trânsito em julgado da sentença final de recurso inadmissível nos tribunais superiores e pendente de julgamento. D A prescrição da pena de multa será sempre de dois anos. E A prescrição começa a contar a partir da data em que a vítima completa dezoito anos de idade apenas em relação aos crimes contra a dignidade sexual que envolvam crianças e adolescentes.$q$,$q$A respeito da extinção da punibilidade, assinale a opção correta à luz do disposto no Código Penal e da jurisprudência dos tribunais superiores. A A retratação do agente não extingue a punibilidade. B Só há efetiva extinção da punibilidade quando cumprida a pena privativa de liberdade e adimplido o pagamento da pena pecuniária, ainda que o condenado comprove hipossuficiência. C Não corre prescrição antes do trânsito em julgado da sentença final de recurso inadmissível nos tribunais superiores e pendente de julgamento. D A prescrição da pena de multa será sempre de dois anos. E A prescrição começa a contar a partir da data em que a vítima completa dezoito anos de idade apenas em relação aos crimes contra a dignidade sexual que envolvam crianças e adolescentes.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,27,$q$Direito Processual Penal$q$,$q$Em relação a conceitos e previsões presentes na Parte Geral do Código Penal, assinale a opção correta. A Se o agente ferir alguém com uma faca no pescoço, com nítida intenção de matar, mas a vítima for socorrida e levada ao hospital e, durante a internação, morrer em decorrência de uma explosão acidental no hospital, o agente responderá por tentativa de homicídio. B Em caso de erro sobre a pessoa, são consideradas as características da vítima real, e não as da pessoa que seria o alvo da ação. C A indenização do dano causado ao ofendido em decorrência do crime importa em renúncia tácita ao direito de queixa, uma vez que tal fato é incompatível com a vontade de exercer esse direito. D A condenação por crime doloso em sentença irrecorrível é causa facultativa de revogação da suspensão condicional da pena. E Incide causa de aumento de pena caso o crime tenha sido executado mediante paga ou promessa de recompensa e em concurso de pessoas.$q$,$q$Em relação a conceitos e previsões presentes na Parte Geral do Código Penal, assinale a opção correta. A Se o agente ferir alguém com uma faca no pescoço, com nítida intenção de matar, mas a vítima for socorrida e levada ao hospital e, durante a internação, morrer em decorrência de uma explosão acidental no hospital, o agente responderá por tentativa de homicídio. B Em caso de erro sobre a pessoa, são consideradas as características da vítima real, e não as da pessoa que seria o alvo da ação. C A indenização do dano causado ao ofendido em decorrência do crime importa em renúncia tácita ao direito de queixa, uma vez que tal fato é incompatível com a vontade de exercer esse direito. D A condenação por crime doloso em sentença irrecorrível é causa facultativa de revogação da suspensão condicional da pena. E Incide causa de aumento de pena caso o crime tenha sido executado mediante paga ou promessa de recompensa e em concurso de pessoas.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,28,$q$Direito Processual Penal$q$,$q$A respeito dos crimes contra o patrimônio, assinale a opção correta. A A Lei n.º 13.964/2019, que alterou o Código Penal, tornou o estelionato um crime de ação penal condicionada à representação da vítima, salvo nos casos em que esta seja idosa com mais de 65 anos de idade. B O roubo em transporte coletivo vazio é circunstância concreta que não justifica a elevação da pena-base. C O rompimento de cadeado e a destruição da fechadura da porta na casa de uma pessoa, feitos com o intuito de efetuar subtração patrimonial da residência mediante uso de arma de fogo, são ações suficientes para configurar o crime de roubo circunstanciado. D Quando o crime de esbulho possessório é praticado com violência, aplica-se somente a pena do esbulho, pois esse tipo penal absorve outros delitos que venham a ser praticados para que ele ocorra. E É isento de pena aquele que pratica crimes contra o patrimônio em desfavor do cônjuge, durante a sociedade conjugal, ainda que haja emprego de violência.$q$,$q$A respeito dos crimes contra o patrimônio, assinale a opção correta. A A Lei n.º 13.964/2019, que alterou o Código Penal, tornou o estelionato um crime de ação penal condicionada à representação da vítima, salvo nos casos em que esta seja idosa com mais de 65 anos de idade. B O roubo em transporte coletivo vazio é circunstância concreta que não justifica a elevação da pena-base. C O rompimento de cadeado e a destruição da fechadura da porta na casa de uma pessoa, feitos com o intuito de efetuar subtração patrimonial da residência mediante uso de arma de fogo, são ações suficientes para configurar o crime de roubo circunstanciado. D Quando o crime de esbulho possessório é praticado com violência, aplica-se somente a pena do esbulho, pois esse tipo penal absorve outros delitos que venham a ser praticados para que ele ocorra. E É isento de pena aquele que pratica crimes contra o patrimônio em desfavor do cônjuge, durante a sociedade conjugal, ainda que haja emprego de violência.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,29,$q$Direito Processual Penal$q$,$q$Acerca do inquérito policial e dos direitos e garantias do investigado, assinale a opção correta. A Conforme entendimento pacificado do STJ, é admitido que a autoridade policial espelhe o aparelho celular do investigado, sem a anuência deste ou ordem judicial, e monitore as conversas de aplicativos de mensagens, a fim de obter provas. B Ao fim do termo circunstanciado de ocorrência, quando houver provas suficientes do delito e provas razoáveis acerca da autoria, a autoridade policial tem o dever de indiciar o suspeito. C O indiciamento realizado pelo delegado de polícia, embora seja um ato formal, dispensa fundamentação acerca do convencimento da autoria e da existência do delito, uma vez que não há alteração do status do indiciado. D O advogado do investigado poderá ter acesso ao procedimento investigatório policial já documentado, para o exercício da defesa, desde que tenha autorização judicial, independentemente da natureza do delito. E O indiciamento pode ser realizado no auto de prisão em flagrante ou no relatório final do inquérito, mas, de acordo com o STJ, não será admitido após o recebimento da denúncia.$q$,$q$Acerca do inquérito policial e dos direitos e garantias do investigado, assinale a opção correta. A Conforme entendimento pacificado do STJ, é admitido que a autoridade policial espelhe o aparelho celular do investigado, sem a anuência deste ou ordem judicial, e monitore as conversas de aplicativos de mensagens, a fim de obter provas. B Ao fim do termo circunstanciado de ocorrência, quando houver provas suficientes do delito e provas razoáveis acerca da autoria, a autoridade policial tem o dever de indiciar o suspeito. C O indiciamento realizado pelo delegado de polícia, embora seja um ato formal, dispensa fundamentação acerca do convencimento da autoria e da existência do delito, uma vez que não há alteração do status do indiciado. D O advogado do investigado poderá ter acesso ao procedimento investigatório policial já documentado, para o exercício da defesa, desde que tenha autorização judicial, independentemente da natureza do delito. E O indiciamento pode ser realizado no auto de prisão em flagrante ou no relatório final do inquérito, mas, de acordo com o STJ, não será admitido após o recebimento da denúncia.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,30,$q$Direito Processual Penal$q$,$q$Em relação ao inquérito policial, assinale a opção correta. A Havendo repercussão interestadual que exija repressão uniforme, o delegado da Polícia Federal poderá apurar crimes cuja apuração seja de competência da justiça estadual, não havendo mácula apta a invalidar a produção de provas. B O delegado de polícia não pode presidir nem instaurar inquérito policial para apurar crime ocorrido fora de sua circunscrição territorial, pois o lugar de consumação do delito é o que define a atribuição da polícia investigativa, em nome do princípio do delegado natural. C Se, no curso de investigações policiais presididas por delegado de polícia civil estadual, sobrevier a federalização do crime, deverá ser mantida a atribuição da polícia civil estadual, uma vez que esta não está subordinada à Polícia Federal e não há, no ordenamento jurídico brasileiro, a possibilidade de instauração do incidente de deslocamento de competência no curso do inquérito. D O prazo para o delegado de polícia civil concluir o inquérito policial é de trinta dias, se o indiciado estiver solto, configurando constrangimento ilegal a superação desse prazo sem autorização judicial, por se tratar de prazo próprio. E Ainda que haja motivo de interesse público, o chefe de polícia civil não pode avocar nem redistribuir o inquérito policial, uma vez que a regra dos atos administrativos não se aplica no âmbito da investigação policial.$q$,$q$Em relação ao inquérito policial, assinale a opção correta. A Havendo repercussão interestadual que exija repressão uniforme, o delegado da Polícia Federal poderá apurar crimes cuja apuração seja de competência da justiça estadual, não havendo mácula apta a invalidar a produção de provas. B O delegado de polícia não pode presidir nem instaurar inquérito policial para apurar crime ocorrido fora de sua circunscrição territorial, pois o lugar de consumação do delito é o que define a atribuição da polícia investigativa, em nome do princípio do delegado natural. C Se, no curso de investigações policiais presididas por delegado de polícia civil estadual, sobrevier a federalização do crime, deverá ser mantida a atribuição da polícia civil estadual, uma vez que esta não está subordinada à Polícia Federal e não há, no ordenamento jurídico brasileiro, a possibilidade de instauração do incidente de deslocamento de competência no curso do inquérito. D O prazo para o delegado de polícia civil concluir o inquérito policial é de trinta dias, se o indiciado estiver solto, configurando constrangimento ilegal a superação desse prazo sem autorização judicial, por se tratar de prazo próprio. E Ainda que haja motivo de interesse público, o chefe de polícia civil não pode avocar nem redistribuir o inquérito policial, uma vez que a regra dos atos administrativos não se aplica no âmbito da investigação policial.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,31,$q$Direito Processual Penal$q$,$q$Assinale a opção correta, relacionada à prisão. A Caso flagre a prática de delito federal, delegado de polícia civil estadual não tem a obrigação legal de efetuar a prisão, pois, nesse contexto, ele está na mesma condição de qualquer pessoa do povo. B Se, durante perseguição policial devido à flagrância da prática de delito, a autoridade policial que estiver no encalço do autor da conduta prendê-lo depois que ele passar para o território de outro município, ela deverá conduzi-lo para a sua circunscrição, para a lavratura do auto de prisão, não havendo necessidade de encaminhá-lo à delegacia de polícia do local da prisão. C Na falta de escrivão, qualquer pessoa designada pela autoridade policial poderá lavrar o auto de prisão, desde que preste compromisso legal; contudo, na falta da autoridade policial na circunscrição, o preso deverá ser apresentado à autoridade da capital do estado. D Para efetuar a prisão, o uso de algemas é permitido em caso de resistência e fundado receio de fuga, desde que justificado por escrito, mas é vedado fazê-lo em mulheres que estejam no período puerperal. E Caso o executor do mandado de prisão veja o réu, durante o dia, entrar em uma casa, ele poderá, desde logo, entrar à força e sozinho em tal residência, arrombando a porta, se necessário, para efetuar a captura do réu, sem necessidade da intimação do morador da residência.$q$,$q$Assinale a opção correta, relacionada à prisão. A Caso flagre a prática de delito federal, delegado de polícia civil estadual não tem a obrigação legal de efetuar a prisão, pois, nesse contexto, ele está na mesma condição de qualquer pessoa do povo. B Se, durante perseguição policial devido à flagrância da prática de delito, a autoridade policial que estiver no encalço do autor da conduta prendê-lo depois que ele passar para o território de outro município, ela deverá conduzi-lo para a sua circunscrição, para a lavratura do auto de prisão, não havendo necessidade de encaminhá-lo à delegacia de polícia do local da prisão. C Na falta de escrivão, qualquer pessoa designada pela autoridade policial poderá lavrar o auto de prisão, desde que preste compromisso legal; contudo, na falta da autoridade policial na circunscrição, o preso deverá ser apresentado à autoridade da capital do estado. D Para efetuar a prisão, o uso de algemas é permitido em caso de resistência e fundado receio de fuga, desde que justificado por escrito, mas é vedado fazê-lo em mulheres que estejam no período puerperal. E Caso o executor do mandado de prisão veja o réu, durante o dia, entrar em uma casa, ele poderá, desde logo, entrar à força e sozinho em tal residência, arrombando a porta, se necessário, para efetuar a captura do réu, sem necessidade da intimação do morador da residência.$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (729_PC_ES_DELEGADO_GABARITOS); não é exibido aos estudantes.$q$),
(2022,32,$q$Direito Processual Penal$q$,$q$Acerca das medidas cautelares diversas da prisão, assinale a opção correta. A Em razão do sistema acusatório e do princípio do contraditório, por previsão expressa do Código de Processo Penal, o juiz não poderá revogar de ofício a medida cautelar ou substitui-la quando verificar a falta de motivo para que ela subsista, tampouco voltar a decretá-la se sobrevierem razões que a justifiquem. B A prática de nova infração penal pelo sujeito que estiver em liberdade provisória pelo pagamento de fiança resultará na perda total do valor depositado a título da fiança, podendo o juiz estabelecer outras medidas cautelares que entender adequadas. C Segundo o Código de Processo Penal, o réu afiançado não pode se ausentar de sua residência por mais de cinco dias sem comunicar o local onde poderá ser encontrado, sob pena de quebramento da fiança. D Se, na delegacia, a autoridade policial conceder a liberdade provisória mediante o pagamento de fiança e o preso tiver o dinheiro em mãos, mas não puder efetuar o depósito de pronto, constando em termo, o valor poderá ser entregue ao escrivão, que, dentro de três dias, deverá dar o destino correto à quantia. E O indiciado que seja maior de oitenta anos ou portador de doença grave, assim como a indiciada gestante, poderá ficar em prisão domiciliar, sendo-lhe permitido ausentar-se de casa se houver anuência da autoridade policial ou judicial.$q$,$q$Acerca das medidas cautelares diversas da prisão, assinale a opção correta. A Em razão do sistema acusatório e do princípio do contraditório, por previsão expressa do Código de Processo Penal, o juiz não poderá revogar de ofício a medida cautelar ou substitui-la quando verificar a falta de motivo para que ela subsista, tampouco voltar a decretá-la se sobrevierem razões que a justifiquem. B A prática de nova infração penal pelo sujeito que estiver em liberdade provisória pelo pagamento de fiança resultará na perda total do valor depositado a título da fiança, podendo o juiz estabelecer outras medidas cautelares que entender adequadas. C Segundo o Código de Processo Penal, o réu afiançado não pode se ausentar de sua residência por mais de cinco dias sem comunicar o local onde poderá ser encontrado, sob pena de quebramento da fiança. D Se, na delegacia, a autoridade policial conceder a liberdade provisória mediante o pagamento de fiança e o preso tiver o dinheiro em mãos, mas não puder efetuar o depósito de pronto, constando em termo, o valor poderá ser entregue ao escrivão, que, dentro de três dias, deverá dar o destino correto à quantia. E O indiciado que seja maior de oitenta anos ou portador de doença grave, assim como a indiciada gestante, poderá ficar em prisão domiciliar, sendo-lhe permitido ausentar-se de casa se houver anuência da autoridade policial ou judicial.$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,33,$q$Direito Processual Penal$q$,$q$A respeito de investigações policiais, assinale a opção correta. A Estando preso o investigado, é proibida a realização de reconhecimento de pessoa por meio de videochamada, ainda que com a anuência do próprio investigado, por se tratar de procedimento que exige a presença da pessoa em sede policial. B A reconstituição simulada consiste no exame do local do crime por peritos, a fim de elucidá-lo mediante a confecção de fotografias, desenhos e esquemas, sem a presença do investigado e de testemunhas, para evitar contaminação do local. C Durante as investigações policiais, por meio de inquérito presidido pelo delegado de polícia, o investigado poderá requisitar diligências, as quais, nessa hipótese, deverão ser obrigatoriamente realizadas, já que a autoridade não pode indeferir tal pedido. D Na comarca em que houver duas circunscrições policiais, a autoridade com atribuição em uma delas deverá requisitar diligências a outra autoridade policial da outra circunscrição, quando, para a conclusão do inquérito, for necessária a análise de indícios ou provas existentes na localidade dessa última circunscrição. E É permitida a condução coercitiva do investigado até a delegacia de polícia para submetê-lo ao procedimento de reconhecimento de pessoa, não havendo mácula ao preceito nemo tenetur se detegere.$q$,$q$A respeito de investigações policiais, assinale a opção correta. A Estando preso o investigado, é proibida a realização de reconhecimento de pessoa por meio de videochamada, ainda que com a anuência do próprio investigado, por se tratar de procedimento que exige a presença da pessoa em sede policial. B A reconstituição simulada consiste no exame do local do crime por peritos, a fim de elucidá-lo mediante a confecção de fotografias, desenhos e esquemas, sem a presença do investigado e de testemunhas, para evitar contaminação do local. C Durante as investigações policiais, por meio de inquérito presidido pelo delegado de polícia, o investigado poderá requisitar diligências, as quais, nessa hipótese, deverão ser obrigatoriamente realizadas, já que a autoridade não pode indeferir tal pedido. D Na comarca em que houver duas circunscrições policiais, a autoridade com atribuição em uma delas deverá requisitar diligências a outra autoridade policial da outra circunscrição, quando, para a conclusão do inquérito, for necessária a análise de indícios ou provas existentes na localidade dessa última circunscrição. E É permitida a condução coercitiva do investigado até a delegacia de polícia para submetê-lo ao procedimento de reconhecimento de pessoa, não havendo mácula ao preceito nemo tenetur se detegere.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,34,$q$Direito Processual Penal$q$,$q$Em relação a busca e apreensão, assinale a opção correta. A Não é permitido o ingresso de agente de polícia em quarto de motel desocupado, para realizar buscas de coisas, quando o estabelecimento estiver aberto a clientes, sendo necessário mandado judicial para o devido ingresso no local, por ele ser equiparado a casa. B Agente de polícia civil não poderá realizar buscas sem mandado judicial em trailer estacionado onde se domicilia pessoa. C É permitida a busca e apreensão por agente da polícia civil, sem mandado judicial, de bens guarnecidos em gabinete de delegado de polícia, uma vez que esse local não recebe proteção constitucional de domicílio. D A busca domiciliar será procedida quando houver o objetivo de prender criminosos ou apreender coisas achadas ou obtidas por meios criminosos, não sendo admitida para apreensão de pessoas vítimas de crimes. E Durante o cumprimento de mandado de busca e apreensão domiciliar com descrição dos objetos a serem apreendidos, caso encontre objeto ilícito não incluído no mandado, a autoridade policial não poderá apreendê-lo, pois necessitará de novo mandado para tanto.$q$,$q$Em relação a busca e apreensão, assinale a opção correta. A Não é permitido o ingresso de agente de polícia em quarto de motel desocupado, para realizar buscas de coisas, quando o estabelecimento estiver aberto a clientes, sendo necessário mandado judicial para o devido ingresso no local, por ele ser equiparado a casa. B Agente de polícia civil não poderá realizar buscas sem mandado judicial em trailer estacionado onde se domicilia pessoa. C É permitida a busca e apreensão por agente da polícia civil, sem mandado judicial, de bens guarnecidos em gabinete de delegado de polícia, uma vez que esse local não recebe proteção constitucional de domicílio. D A busca domiciliar será procedida quando houver o objetivo de prender criminosos ou apreender coisas achadas ou obtidas por meios criminosos, não sendo admitida para apreensão de pessoas vítimas de crimes. E Durante o cumprimento de mandado de busca e apreensão domiciliar com descrição dos objetos a serem apreendidos, caso encontre objeto ilícito não incluído no mandado, a autoridade policial não poderá apreendê-lo, pois necessitará de novo mandado para tanto.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,35,$q$Direito Processual Penal$q$,$q$Acerca dos atos do delegado de polícia durante o inquérito policial, assinale a opção correta. A O delegado de polícia poderá instaurar inquérito policial para apurar delitos específicos e complexos que chegarem ao seu conhecimento, sendo-lhe autorizada, ainda, a realização de fishing expedition, por ser um procedimento investigatório especial em razão da artimanha do modus operandi. B Em caso de crime que deixar vestígios, se houver a confissão do indiciado, a autoridade policial poderá dispensar o encaminhamento da vítima para a realização do exame de corpo de delito. C Diante de notitia criminis inqualificada, antes de determinar a abertura do inquérito policial, o delegado de polícia deve promover a diligência de verificação de procedência das informações, a fim de evitar delação inescrupulosa. D O delegado de polícia poderá interrogar pessoa inimputável presa em flagrante, não sendo possível a nomeação de curador para acompanhar o ato. E O delegado de polícia poderá realizar o interrogatório, sem a participação de advogado, ainda que o indiciado informe que deseja a presença de seu advogado no ato.$q$,$q$Acerca dos atos do delegado de polícia durante o inquérito policial, assinale a opção correta. A O delegado de polícia poderá instaurar inquérito policial para apurar delitos específicos e complexos que chegarem ao seu conhecimento, sendo-lhe autorizada, ainda, a realização de fishing expedition, por ser um procedimento investigatório especial em razão da artimanha do modus operandi. B Em caso de crime que deixar vestígios, se houver a confissão do indiciado, a autoridade policial poderá dispensar o encaminhamento da vítima para a realização do exame de corpo de delito. C Diante de notitia criminis inqualificada, antes de determinar a abertura do inquérito policial, o delegado de polícia deve promover a diligência de verificação de procedência das informações, a fim de evitar delação inescrupulosa. D O delegado de polícia poderá interrogar pessoa inimputável presa em flagrante, não sendo possível a nomeação de curador para acompanhar o ato. E O delegado de polícia poderá realizar o interrogatório, sem a participação de advogado, ainda que o indiciado informe que deseja a presença de seu advogado no ato.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,36,$q$Direito Administrativo$q$,$q$Nos termos da Lei n.º 10.520/2002, em licitação na modalidade pregão, somente participarão da sessão de lances o autor da proposta de menor valor e os participantes que apresentarem ofertas com preços superiores ao menor valor em até A 5%. B 10%. C 15%. D 20%. E 25%.$q$,$q$Nos termos da Lei n.º 10.520/2002, em licitação na modalidade pregão, somente participarão da sessão de lances o autor da proposta de menor valor e os participantes que apresentarem ofertas com preços superiores ao menor valor em até A 5%. B 10%. C 15%. D 20%. E 25%.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,37,$q$Direito Administrativo$q$,$q$No que tange aos institutos da descentralização e da desconcentração, julgue os itens a seguir. I A principal diferença entre esses institutos decorre do número de pessoas jurídicas envolvidas. II A descentralização ocorre no âmbito de uma única pessoa jurídica. III A desconcentração administrativa acontece quando a administração reparte atribuições e competências dentro de um mesmo órgão. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,$q$No que tange aos institutos da descentralização e da desconcentração, julgue os itens a seguir. I A principal diferença entre esses institutos decorre do número de pessoas jurídicas envolvidas. II A descentralização ocorre no âmbito de uma única pessoa jurídica. III A desconcentração administrativa acontece quando a administração reparte atribuições e competências dentro de um mesmo órgão. Assinale a opção correta. A Apenas o item I está certo. B Apenas o item II está certo. C Apenas os itens I e III estão certos. D Apenas os itens II e III estão certos. E Todos os itens estão certos.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,38,$q$Direito Administrativo$q$,$q$Acerca do conceito de ato administrativo, assinale a opção correta. A Ato administrativo é a declaração do Estado, ou de quem o represente, que produz efeitos jurídicos imediatos, com observância da lei, sob regime jurídico de direito público e sujeito a controle pelo Poder Judiciário. B Ato administrativo é aquele que decorre de acontecimentos naturais que independem da vontade humana. C Ato administrativo é aquele que ocorre quando o fato corresponde à descrição contida na norma legal. D Ato administrativo é aquele que ocorre quando o fato descrito na norma produz efeitos no campo do direito administrativo. E Ato administrativo é todo ato praticado no exercício da função administrativa.$q$,$q$Acerca do conceito de ato administrativo, assinale a opção correta. A Ato administrativo é a declaração do Estado, ou de quem o represente, que produz efeitos jurídicos imediatos, com observância da lei, sob regime jurídico de direito público e sujeito a controle pelo Poder Judiciário. B Ato administrativo é aquele que decorre de acontecimentos naturais que independem da vontade humana. C Ato administrativo é aquele que ocorre quando o fato corresponde à descrição contida na norma legal. D Ato administrativo é aquele que ocorre quando o fato descrito na norma produz efeitos no campo do direito administrativo. E Ato administrativo é todo ato praticado no exercício da função administrativa.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,39,$q$Direito Administrativo$q$,$q$Em relação à improbidade administrativa, julgue os itens a seguir, com base na Lei n.º 8.429/1992. I Embora sem tipificação na Constituição Federal de 1988, a suspensão dos direitos políticos é prevista na Lei n.º 8.429/1992 como sanção aplicável por ato de improbidade administrativa, independentemente de eventuais sanções penais, civis e administrativas cominadas. II São espécies de atos de improbidade administrativa aqueles que atentam contra o decoro parlamentar e contra a dignidade da justiça. III Os herdeiros daquele que causar lesão ao patrimônio público estarão sujeitos às cominações legais até o limite do valor da herança ou do patrimônio transferido. Assinale a opção correta. A Nenhum item está certo. B Apenas o item II está certo. C Apenas o item III está certo. D Apenas os itens I e II estão certos. E Apenas os itens I e III estão certos.$q$,$q$Em relação à improbidade administrativa, julgue os itens a seguir, com base na Lei n.º 8.429/1992. I Embora sem tipificação na Constituição Federal de 1988, a suspensão dos direitos políticos é prevista na Lei n.º 8.429/1992 como sanção aplicável por ato de improbidade administrativa, independentemente de eventuais sanções penais, civis e administrativas cominadas. II São espécies de atos de improbidade administrativa aqueles que atentam contra o decoro parlamentar e contra a dignidade da justiça. III Os herdeiros daquele que causar lesão ao patrimônio público estarão sujeitos às cominações legais até o limite do valor da herança ou do patrimônio transferido. Assinale a opção correta. A Nenhum item está certo. B Apenas o item II está certo. C Apenas o item III está certo. D Apenas os itens I e II estão certos. E Apenas os itens I e III estão certos.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,40,$q$Direito Administrativo$q$,$q$A respeito do poder de polícia, julgue os próximos itens. I Segundo o texto constitucional, o poder de polícia é exercido exclusivamente pelas corporações especializadas da polícia civil e da polícia militar. II Para o exercício adequado do poder de polícia, é necessário que a administração pública obtenha previamente autorização do Poder Judiciário. III No exercício do poder de polícia, o município poderá estabelecer os horários de funcionamento dos estabelecimentos comerciais situados em seu território. Assinale a opção correta. A Nenhum item está certo. B Apenas o item II está certo. C Apenas o item III está certo. D Apenas os itens I e II estão certos. E Apenas os itens I e III estão certos.$q$,$q$A respeito do poder de polícia, julgue os próximos itens. I Segundo o texto constitucional, o poder de polícia é exercido exclusivamente pelas corporações especializadas da polícia civil e da polícia militar. II Para o exercício adequado do poder de polícia, é necessário que a administração pública obtenha previamente autorização do Poder Judiciário. III No exercício do poder de polícia, o município poderá estabelecer os horários de funcionamento dos estabelecimentos comerciais situados em seu território. Assinale a opção correta. A Nenhum item está certo. B Apenas o item II está certo. C Apenas o item III está certo. D Apenas os itens I e II estão certos. E Apenas os itens I e III estão certos.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,41,$q$Direito Administrativo$q$,$q$Acerca dos atos administrativos em espécie, assinale a opção correta. A Licença é o ato administrativo unilateral e vinculado pelo qual a administração pública faculta àquele que preencha os requisitos legais o exercício de uma atividade. B Visto é o ato unilateral e vinculado pelo qual a administração pública reconhece a legalidade de um ato jurídico administrativo. C Admissão é o ato bilateral e vinculado pelo qual a administração pública reconhece ao particular que preencha os requisitos legais o direito à prestação de um serviço público. D Homologação é o ato pelo qual os órgãos consultivos da administração pública emitem opinião sobre assuntos técnicos ou jurídicos de sua competência. E Aprovação é um ato bilateral e vinculado pelo qual se exerce o controle a priori ou a posteriori do ato administrativo.$q$,$q$Acerca dos atos administrativos em espécie, assinale a opção correta. A Licença é o ato administrativo unilateral e vinculado pelo qual a administração pública faculta àquele que preencha os requisitos legais o exercício de uma atividade. B Visto é o ato unilateral e vinculado pelo qual a administração pública reconhece a legalidade de um ato jurídico administrativo. C Admissão é o ato bilateral e vinculado pelo qual a administração pública reconhece ao particular que preencha os requisitos legais o direito à prestação de um serviço público. D Homologação é o ato pelo qual os órgãos consultivos da administração pública emitem opinião sobre assuntos técnicos ou jurídicos de sua competência. E Aprovação é um ato bilateral e vinculado pelo qual se exerce o controle a priori ou a posteriori do ato administrativo.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,42,$q$Direito Administrativo$q$,$q$Nos contratos administrativos, é obrigatória a adoção de garantia, ficando a critério do contratado optar por uma das que estão previstas na Lei n.º 8.666/1993. Duas das modalidades de garantia estabelecidas nessa legislação são A bens imóveis e debêntures conversíveis em ações. B caução em dinheiro e bens imóveis. C debêntures conversíveis em ações e seguro-garantia. D seguro-garantia e fiança bancária. E fiança bancária e bens imóveis.$q$,$q$Nos contratos administrativos, é obrigatória a adoção de garantia, ficando a critério do contratado optar por uma das que estão previstas na Lei n.º 8.666/1993. Duas das modalidades de garantia estabelecidas nessa legislação são A bens imóveis e debêntures conversíveis em ações. B caução em dinheiro e bens imóveis. C debêntures conversíveis em ações e seguro-garantia. D seguro-garantia e fiança bancária. E fiança bancária e bens imóveis.$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,43,$q$Direito Constitucional$q$,$q$Assinale a opção correta a respeito dos direitos e garantias fundamentais. A A existência de denúncia anônima da prática de tráfico de drogas configura fundada razão a autorizar o ingresso policial no domicílio do denunciado sem o seu consentimento ou sem determinação judicial. B É vedado ao Poder Judiciário impor à administração pública obrigação de executar obras emergenciais em estabelecimentos prisionais, em razão do postulado da reserva do possível. C É inconstitucional o compartilhamento, sem autorização judicial, de procedimento fiscalizatório da Receita Federal do Brasil com a polícia. D A omissão injustificada da administração pública em providenciar a disponibilização de banho quente nos estabelecimentos prisionais fere a dignidade dos presos sob sua custódia. E Veículo de imprensa não possui direito líquido e certo a obter dados públicos sobre óbitos relacionados a ocorrências policiais.$q$,$q$Assinale a opção correta a respeito dos direitos e garantias fundamentais. A A existência de denúncia anônima da prática de tráfico de drogas configura fundada razão a autorizar o ingresso policial no domicílio do denunciado sem o seu consentimento ou sem determinação judicial. B É vedado ao Poder Judiciário impor à administração pública obrigação de executar obras emergenciais em estabelecimentos prisionais, em razão do postulado da reserva do possível. C É inconstitucional o compartilhamento, sem autorização judicial, de procedimento fiscalizatório da Receita Federal do Brasil com a polícia. D A omissão injustificada da administração pública em providenciar a disponibilização de banho quente nos estabelecimentos prisionais fere a dignidade dos presos sob sua custódia. E Veículo de imprensa não possui direito líquido e certo a obter dados públicos sobre óbitos relacionados a ocorrências policiais.$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,44,$q$Direito Constitucional$q$,$q$Constitui objetivo fundamental da República Federativa do Brasil A o valor social do trabalho e da livre iniciativa. B a solução pacífica dos conflitos. C o repúdio ao terrorismo e ao racismo. D a dignidade da pessoa humana. E a garantia do desenvolvimento nacional.$q$,$q$Constitui objetivo fundamental da República Federativa do Brasil A o valor social do trabalho e da livre iniciativa. B a solução pacífica dos conflitos. C o repúdio ao terrorismo e ao racismo. D a dignidade da pessoa humana. E a garantia do desenvolvimento nacional.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,45,$q$Direito Constitucional$q$,$q$Com base no disposto na Constituição Federal de 1988 (CF/88) e no entendimento do Supremo Tribunal Federal, assinale a opção correta acerca dos direitos sociais. A É vedada a fixação de piso salarial em múltiplos do salário mínimo, ainda que inexistam reajustes automáticos. B É vedada a dispensa do empregado sindicalizado a partir do registro de sua candidatura a cargo de direção ou representação sindical e, se eleito, até seis meses após o final do mandato, salvo na hipótese de falta grave. C O servidor público que seja pai monoparental faz jus à licença maternidade e ao salário maternidade pelo prazo de 180 dias. D Policial civil tem direito a receber seguro desemprego, em caso de desemprego involuntário. E Exige-se a autorização do Estado para a fundação de sindicato.$q$,$q$Com base no disposto na Constituição Federal de 1988 (CF/88) e no entendimento do Supremo Tribunal Federal, assinale a opção correta acerca dos direitos sociais. A É vedada a fixação de piso salarial em múltiplos do salário mínimo, ainda que inexistam reajustes automáticos. B É vedada a dispensa do empregado sindicalizado a partir do registro de sua candidatura a cargo de direção ou representação sindical e, se eleito, até seis meses após o final do mandato, salvo na hipótese de falta grave. C O servidor público que seja pai monoparental faz jus à licença maternidade e ao salário maternidade pelo prazo de 180 dias. D Policial civil tem direito a receber seguro desemprego, em caso de desemprego involuntário. E Exige-se a autorização do Estado para a fundação de sindicato.$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (729_PC_ES_DELEGADO_GABARITOS); não é exibido aos estudantes.$q$),
(2022,46,$q$Direito Constitucional$q$,$q$É autorizada a intervenção do estado no município quando A não tiver sido aplicado o mínimo exigido da receita municipal na manutenção e desenvolvimento da seguridade social. B não tiver sido aplicado o mínimo exigido da receita municipal na manutenção e desenvolvimento do ensino. C deixar de ser paga, sem motivo de força maior, por pelo menos três anos consecutivos, a dívida fundada. D o tribunal de justiça der provimento a representação para assegurar a observância de princípios indicados na Lei Orgânica municipal. E forem praticados, na administração municipal, atos de corrupção devidamente comprovados.$q$,$q$É autorizada a intervenção do estado no município quando A não tiver sido aplicado o mínimo exigido da receita municipal na manutenção e desenvolvimento da seguridade social. B não tiver sido aplicado o mínimo exigido da receita municipal na manutenção e desenvolvimento do ensino. C deixar de ser paga, sem motivo de força maior, por pelo menos três anos consecutivos, a dívida fundada. D o tribunal de justiça der provimento a representação para assegurar a observância de princípios indicados na Lei Orgânica municipal. E forem praticados, na administração municipal, atos de corrupção devidamente comprovados.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,47,$q$Direito Constitucional$q$,$q$Acerca da defesa do Estado e das instituições democráticas, assinale a opção correta. A Decretado o estado de defesa ou sua prorrogação, o presidente da República, dentro de vinte e quatro horas, submeterá o ato com a respectiva justificação ao Congresso Nacional, que decidirá por maioria absoluta. B O Congresso Nacional apreciará o decreto dentro de cinco dias contados de seu recebimento, devendo continuar funcionando enquanto vigorar o estado de defesa. C O tempo de duração do estado de defesa não será superior a 45 dias, podendo ser prorrogado uma vez, por igual período, se persistirem as razões que justificaram a sua decretação. D Cessado o estado de defesa ou o estado de sítio, cessarão também seus efeitos, não podendo haver a responsabilização pelos ilícitos cometidos por seus executores ou agentes, haja vista o seu caráter excepcional. E Na vigência do estado de defesa, poderá ser tomada medida de detenção em edifício não destinado a acusados ou condenados por crimes comuns.$q$,$q$Acerca da defesa do Estado e das instituições democráticas, assinale a opção correta. A Decretado o estado de defesa ou sua prorrogação, o presidente da República, dentro de vinte e quatro horas, submeterá o ato com a respectiva justificação ao Congresso Nacional, que decidirá por maioria absoluta. B O Congresso Nacional apreciará o decreto dentro de cinco dias contados de seu recebimento, devendo continuar funcionando enquanto vigorar o estado de defesa. C O tempo de duração do estado de defesa não será superior a 45 dias, podendo ser prorrogado uma vez, por igual período, se persistirem as razões que justificaram a sua decretação. D Cessado o estado de defesa ou o estado de sítio, cessarão também seus efeitos, não podendo haver a responsabilização pelos ilícitos cometidos por seus executores ou agentes, haja vista o seu caráter excepcional. E Na vigência do estado de defesa, poderá ser tomada medida de detenção em edifício não destinado a acusados ou condenados por crimes comuns.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,48,$q$Direito Constitucional$q$,$q$De acordo com o disposto na CF/88, a criação e o desmembramento de municípios serão realizados por meio de A lei complementar municipal, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal. B lei complementar estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal, apresentados e publicados na forma da lei. C lei estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal. D decreto estadual, dentro do período determinado por lei complementar estadual, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal. E lei estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta às populações dos municípios envolvidos, mediante referendo, após divulgação dos estudos de viabilidade municipal, apresentados e publicados na forma da lei.$q$,$q$De acordo com o disposto na CF/88, a criação e o desmembramento de municípios serão realizados por meio de A lei complementar municipal, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal. B lei complementar estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal, apresentados e publicados na forma da lei. C lei estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal. D decreto estadual, dentro do período determinado por lei complementar estadual, e dependerão de consulta prévia, mediante plebiscito, às populações dos municípios envolvidos, após divulgação dos estudos de viabilidade municipal. E lei estadual, dentro do período determinado por lei complementar federal, e dependerão de consulta às populações dos municípios envolvidos, mediante referendo, após divulgação dos estudos de viabilidade municipal, apresentados e publicados na forma da lei.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,49,$q$Direito Constitucional$q$,$q$A respeito das medidas provisórias, assinale a opção correta. A O Poder Legislativo pode emendar projeto de lei de conversão de medida provisória, quando a emenda estiver associada ao tema e à finalidade original da referida medida. B É vedado ao Poder Judiciário, sob pena de violação do princípio da separação dos poderes, realizar o controle dos pressupostos de relevância e urgência das medidas provisórias. C É constitucional lei decorrente de conversão de medida provisória, cujo conteúdo normativo caracterize a reedição, na mesma sessão legislativa, de medida provisória que ainda não tenha sido apreciada pelo Congresso Nacional dentro do prazo estabelecido pela CF. D O trancamento de pauta em razão de medidas provisórias não votadas no prazo de 45 dias atinge projetos de lei complementar. E Não é possível a edição de medidas provisórias que digam respeito ao meio ambiente.$q$,$q$A respeito das medidas provisórias, assinale a opção correta. A O Poder Legislativo pode emendar projeto de lei de conversão de medida provisória, quando a emenda estiver associada ao tema e à finalidade original da referida medida. B É vedado ao Poder Judiciário, sob pena de violação do princípio da separação dos poderes, realizar o controle dos pressupostos de relevância e urgência das medidas provisórias. C É constitucional lei decorrente de conversão de medida provisória, cujo conteúdo normativo caracterize a reedição, na mesma sessão legislativa, de medida provisória que ainda não tenha sido apreciada pelo Congresso Nacional dentro do prazo estabelecido pela CF. D O trancamento de pauta em razão de medidas provisórias não votadas no prazo de 45 dias atinge projetos de lei complementar. E Não é possível a edição de medidas provisórias que digam respeito ao meio ambiente.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,50,$q$Direito Constitucional$q$,$q$Acerca do Código de Conduta para os Funcionários Responsáveis pela Aplicação da Lei (Resolução da ONU n.º 34-169/1979), assinale a opção correta. A As informações de natureza confidencial, em qualquer hipótese, devem ser mantidas em segredo. B Em seu âmbito de aplicação, o código em apreço não abrange as polícias militares e, em ações de garantia da lei e da ordem, as Forças Armadas. C O dever de assegurar cuidados médicos às vítimas de violação da lei não tem previsão expressa. D É possível alegar excludente de culpabilidade decorrente de ordem superior para eximir-se da culpa de tratamento degradante. E A abstenção do cometimento de atos de corrupção não tem previsão expressa.$q$,$q$Acerca do Código de Conduta para os Funcionários Responsáveis pela Aplicação da Lei (Resolução da ONU n.º 34-169/1979), assinale a opção correta. A As informações de natureza confidencial, em qualquer hipótese, devem ser mantidas em segredo. B Em seu âmbito de aplicação, o código em apreço não abrange as polícias militares e, em ações de garantia da lei e da ordem, as Forças Armadas. C O dever de assegurar cuidados médicos às vítimas de violação da lei não tem previsão expressa. D É possível alegar excludente de culpabilidade decorrente de ordem superior para eximir-se da culpa de tratamento degradante. E A abstenção do cometimento de atos de corrupção não tem previsão expressa.$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (729_PC_ES_DELEGADO_GABARITOS); não é exibido aos estudantes.$q$),
(2022,51,$q$Direito Constitucional$q$,$q$A Declaração Universal dos Direitos Humanos A prevê a possibilidade de suspensão de direitos em situações excepcionais. B prevê a proteção contra a tortura, mas excepciona dessa proteção os criminosos de guerra. C estabelece, para a vítima de perseguição, o direito de pedir refúgio, independentemente do motivo da perseguição. D prevê direitos sociais, neles incluídos, entre outros, os direitos a trabalho e remuneração justa e à filiação a sindicatos. E é omissa relativamente à apatridia.$q$,$q$A Declaração Universal dos Direitos Humanos A prevê a possibilidade de suspensão de direitos em situações excepcionais. B prevê a proteção contra a tortura, mas excepciona dessa proteção os criminosos de guerra. C estabelece, para a vítima de perseguição, o direito de pedir refúgio, independentemente do motivo da perseguição. D prevê direitos sociais, neles incluídos, entre outros, os direitos a trabalho e remuneração justa e à filiação a sindicatos. E é omissa relativamente à apatridia.$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,52,$q$Direitos Humanos$q$,$q$À luz da Lei n.º 13.060/2014, que disciplina o uso dos instrumentos de menor potencial ofensivo pelos agentes de segurança pública no território nacional, assinale a opção correta. A Os órgãos de segurança pública deverão priorizar a utilização dos instrumentos de menor potencial ofensivo, mesmo que o seu uso ponha em risco a integridade física ou psíquica dos policiais. B Não é legítimo o uso de arma de fogo contra pessoa em fuga que esteja armada ou que não represente risco imediato de morte ou de lesão aos agentes de segurança pública ou a terceiros. C É legítimo o uso de arma de fogo contra veículo que desrespeite bloqueio policial em via pública somente quando o ato represente risco de morte ou lesão aos agentes de segurança pública ou a terceiros. D Sempre que o uso da força pelos agentes de segurança pública causar ferimentos em pessoas, serão assegurados imediata assistência e socorro médico aos feridos, sem a necessidade de comunicação do ocorrido à família ou à pessoa por eles indicada. E São considerados instrumentos de menor potencial ofensivo os projetados especificamente para, com baixa ou média probabilidade de causar mortes ou lesões permanentes, conter, debilitar ou incapacitar temporariamente pessoas.$q$,$q$À luz da Lei n.º 13.060/2014, que disciplina o uso dos instrumentos de menor potencial ofensivo pelos agentes de segurança pública no território nacional, assinale a opção correta. A Os órgãos de segurança pública deverão priorizar a utilização dos instrumentos de menor potencial ofensivo, mesmo que o seu uso ponha em risco a integridade física ou psíquica dos policiais. B Não é legítimo o uso de arma de fogo contra pessoa em fuga que esteja armada ou que não represente risco imediato de morte ou de lesão aos agentes de segurança pública ou a terceiros. C É legítimo o uso de arma de fogo contra veículo que desrespeite bloqueio policial em via pública somente quando o ato represente risco de morte ou lesão aos agentes de segurança pública ou a terceiros. D Sempre que o uso da força pelos agentes de segurança pública causar ferimentos em pessoas, serão assegurados imediata assistência e socorro médico aos feridos, sem a necessidade de comunicação do ocorrido à família ou à pessoa por eles indicada. E São considerados instrumentos de menor potencial ofensivo os projetados especificamente para, com baixa ou média probabilidade de causar mortes ou lesões permanentes, conter, debilitar ou incapacitar temporariamente pessoas.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,53,$q$Direitos Humanos$q$,$q$Considerando a interpretação doutrinária da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes (Decreto n.º 40/1991), assinale a opção correta. A A convenção em apreço prevê quatro elementos definidores do conceito de tortura: natureza do ato, dolo do torturador, finalidade e envolvimento direto ou indireto de um agente público. B Atos omissivos do agente público não podem configurar tortura. C A negligência pode configurar tortura praticada pelo agente público. D Para se configurar a tortura, deve haver, no mínimo, o consentimento ou a aquiescência do agente público, não bastando para tal a instigação. E Será considerada legal a tortura cuja finalidade esteja estritamente ligada à obtenção de confissão ou informação, não comportando situações como a discriminação.$q$,$q$Considerando a interpretação doutrinária da Convenção contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes (Decreto n.º 40/1991), assinale a opção correta. A A convenção em apreço prevê quatro elementos definidores do conceito de tortura: natureza do ato, dolo do torturador, finalidade e envolvimento direto ou indireto de um agente público. B Atos omissivos do agente público não podem configurar tortura. C A negligência pode configurar tortura praticada pelo agente público. D Para se configurar a tortura, deve haver, no mínimo, o consentimento ou a aquiescência do agente público, não bastando para tal a instigação. E Será considerada legal a tortura cuja finalidade esteja estritamente ligada à obtenção de confissão ou informação, não comportando situações como a discriminação.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,54,$q$Direitos Humanos$q$,$q$Em relação ao combate à impunidade e ao dever de investigar, processar e punir, assinale a opção correta à luz da Corte Interamericana de Direitos Humanos, conforme a doutrina. A O dever de investigar, processar e punir consta expressamente na Convenção Americana de Direitos Humanos. B O direito à verdade não é considerado um dos desdobramentos da obrigação de investigar. C A obrigação de investigar e de prevenir crimes é de resultado. D O combate à impunidade ainda não é considerado uma obrigação erga omnes. E A partir da notitia criminis, as autoridades policiais devem iniciar, de ofício e sem demora, uma investigação séria, imparcial e efetiva por todos os meios legais disponíveis.$q$,$q$Em relação ao combate à impunidade e ao dever de investigar, processar e punir, assinale a opção correta à luz da Corte Interamericana de Direitos Humanos, conforme a doutrina. A O dever de investigar, processar e punir consta expressamente na Convenção Americana de Direitos Humanos. B O direito à verdade não é considerado um dos desdobramentos da obrigação de investigar. C A obrigação de investigar e de prevenir crimes é de resultado. D O combate à impunidade ainda não é considerado uma obrigação erga omnes. E A partir da notitia criminis, as autoridades policiais devem iniciar, de ofício e sem demora, uma investigação séria, imparcial e efetiva por todos os meios legais disponíveis.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,55,$q$Direitos Humanos$q$,$q$Assinale a opção correta conforme a Convenção Americana de Direitos Humanos (Pacto de São José da Costa Rica). A A Comissão Interamericana e a Corte Interamericana são treaty bodies da Convenção Americana, fato que implica a submissão obrigatória a sua jurisdição, sem qualquer exigência adicional quando da sua ratificação. B Os direitos econômicos, sociais e culturais não foram previstos no pacto de São José da Costa Rica, encontrando assento no protocolo de São Salvador. C Os direitos políticos são passíveis de suspensão em caso de guerra, perigo público ou outra emergência que ameace a independência ou a segurança. D A convenção em apreço prevê uma cláusula de abertura para a inclusão de outros direitos por meio de emendas ou de protocolos adicionais. E O direito de denúncia da referida convenção pode ser exercido após ultrapassados cinco anos da sua entrada em vigor; porém, os direitos devem ser respeitados até dois anos após a notificação.$q$,$q$Assinale a opção correta conforme a Convenção Americana de Direitos Humanos (Pacto de São José da Costa Rica). A A Comissão Interamericana e a Corte Interamericana são treaty bodies da Convenção Americana, fato que implica a submissão obrigatória a sua jurisdição, sem qualquer exigência adicional quando da sua ratificação. B Os direitos econômicos, sociais e culturais não foram previstos no pacto de São José da Costa Rica, encontrando assento no protocolo de São Salvador. C Os direitos políticos são passíveis de suspensão em caso de guerra, perigo público ou outra emergência que ameace a independência ou a segurança. D A convenção em apreço prevê uma cláusula de abertura para a inclusão de outros direitos por meio de emendas ou de protocolos adicionais. E O direito de denúncia da referida convenção pode ser exercido após ultrapassados cinco anos da sua entrada em vigor; porém, os direitos devem ser respeitados até dois anos após a notificação.$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,56,$q$Direitos Humanos$q$,$q$Acerca do Sistema Interamericano de Direitos Humanos, no que tange ao caso Favela Nova Brasília, assinale a opção correta. A A expressão “autos de resistência” deve ser abolida, pois ela provoca uma revitimização, contribuindo para a impunidade dos agentes criminosos. B A polícia civil pode investigar seus próprios agentes quando estes forem suspeitos da prática de crimes, sobretudo quando essa prática importar em graves violações de direitos humanos. C A participação das vítimas não está restrita à fase judicial (assistente da acusação), podendo ocorrer durante as investigações, com acesso ao inquérito policial. D A preliminar de incompetência ratione tempore foi acolhida, o que impediu a condenação do Brasil pela Corte. E O controle externo da atividade policial pode limitar-se a supervisionar, à distância, as investigações realizadas por delegados da própria polícia.$q$,$q$Acerca do Sistema Interamericano de Direitos Humanos, no que tange ao caso Favela Nova Brasília, assinale a opção correta. A A expressão “autos de resistência” deve ser abolida, pois ela provoca uma revitimização, contribuindo para a impunidade dos agentes criminosos. B A polícia civil pode investigar seus próprios agentes quando estes forem suspeitos da prática de crimes, sobretudo quando essa prática importar em graves violações de direitos humanos. C A participação das vítimas não está restrita à fase judicial (assistente da acusação), podendo ocorrer durante as investigações, com acesso ao inquérito policial. D A preliminar de incompetência ratione tempore foi acolhida, o que impediu a condenação do Brasil pela Corte. E O controle externo da atividade policial pode limitar-se a supervisionar, à distância, as investigações realizadas por delegados da própria polícia.$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (729_PC_ES_DELEGADO_GABARITOS); não é exibido aos estudantes.$q$),
(2022,57,$q$Direito Civil$q$,$q$Em janeiro de 2020, João, com 70 anos de idade, foi vítima de estelionato praticado por José. A ação penal foi oferecida pelo Ministério Público (MP) sem a representação de João, motivo pelo qual o juízo criminal extinguiu a ação penal, com base no inciso IV do § 5.º do art. 171 do Código Penal, alegando ilegitimidade do MP. Nessa situação hipotética, tendo a sentença penal transitado em julgado em janeiro de 2021, João poderá ingressar em juízo para obter a reparação civil do dano até janeiro de A 2023, haja vista o prazo prescricional de 3 anos, a contar da ocorrência do evento danoso. B 2025, em razão do prazo prescricional de 5 anos, a contar da ocorrência do evento danoso. C 2023, em razão do prazo prescricional de 2 anos, a contar do trânsito em julgado da sentença penal. D 2024, visto que o prazo prescricional de 3 anos começa a fluir do trânsito em julgado da sentença penal. E 2026, visto que o prazo prescricional de 5 anos começa a fluir do trânsito em julgado da sentença penal.$q$,$q$Em janeiro de 2020, João, com 70 anos de idade, foi vítima de estelionato praticado por José. A ação penal foi oferecida pelo Ministério Público (MP) sem a representação de João, motivo pelo qual o juízo criminal extinguiu a ação penal, com base no inciso IV do § 5.º do art. 171 do Código Penal, alegando ilegitimidade do MP. Nessa situação hipotética, tendo a sentença penal transitado em julgado em janeiro de 2021, João poderá ingressar em juízo para obter a reparação civil do dano até janeiro de A 2023, haja vista o prazo prescricional de 3 anos, a contar da ocorrência do evento danoso. B 2025, em razão do prazo prescricional de 5 anos, a contar da ocorrência do evento danoso. C 2023, em razão do prazo prescricional de 2 anos, a contar do trânsito em julgado da sentença penal. D 2024, visto que o prazo prescricional de 3 anos começa a fluir do trânsito em julgado da sentença penal. E 2026, visto que o prazo prescricional de 5 anos começa a fluir do trânsito em julgado da sentença penal.$q$,'D',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,58,$q$Direito Civil$q$,$q$Assinale a opção correta no que diz respeito às obrigações alternativas previstas no Código Civil. A Cabe ao credor fazer a escolha da coisa. B Se todas as prestações se tornarem impossíveis, sem culpa do devedor, extinguir-se-á a obrigação. C Quando a obrigação envolver prestações periódicas, a faculdade de opção deverá ser exercida na primeira prestação. D Pode o devedor obrigar o credor a receber parte em uma prestação e parte em outra. E Havendo pluralidade de credores e não havendo unanimidade entre eles, decidirá o juiz.$q$,$q$Assinale a opção correta no que diz respeito às obrigações alternativas previstas no Código Civil. A Cabe ao credor fazer a escolha da coisa. B Se todas as prestações se tornarem impossíveis, sem culpa do devedor, extinguir-se-á a obrigação. C Quando a obrigação envolver prestações periódicas, a faculdade de opção deverá ser exercida na primeira prestação. D Pode o devedor obrigar o credor a receber parte em uma prestação e parte em outra. E Havendo pluralidade de credores e não havendo unanimidade entre eles, decidirá o juiz.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,59,$q$Direito Civil$q$,$q$De acordo com as disposições da legislação civil em vigência acerca de negócios jurídicos, assinale a opção correta. A A manifestação de vontade não subsiste se o autor houver feito reserva mental. B São dois os requisitos para a validade do negócio jurídico: agente capaz e objeto lícito, possível e determinado. C O ato de confirmação dispensa a substância do negócio jurídico celebrado, bastando a vontade expressa de mantê-lo. D A invalidade do instrumento induz a do negócio jurídico. E São anuláveis os negócios jurídicos cujas declarações de vontade tenham emanado de erro substancial passível de ser percebido por pessoa de diligência normal, em face das circunstâncias do negócio.$q$,$q$De acordo com as disposições da legislação civil em vigência acerca de negócios jurídicos, assinale a opção correta. A A manifestação de vontade não subsiste se o autor houver feito reserva mental. B São dois os requisitos para a validade do negócio jurídico: agente capaz e objeto lícito, possível e determinado. C O ato de confirmação dispensa a substância do negócio jurídico celebrado, bastando a vontade expressa de mantê-lo. D A invalidade do instrumento induz a do negócio jurídico. E São anuláveis os negócios jurídicos cujas declarações de vontade tenham emanado de erro substancial passível de ser percebido por pessoa de diligência normal, em face das circunstâncias do negócio.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,60,$q$Direito Civil$q$,$q$Paula celebrou com José contrato de compra e venda de um ponto comercial na Praia do Morro, em Guarapari – ES. No contrato, ficou estabelecido que José pagaria o preço combinado em dez parcelas iguais e a ele seria transferida a posse após o pagamento da 1.ª parcela. Ainda, havia cláusula resolutiva expressa no sentido de que, em caso de inadimplemento, Paula retomaria a posse do ponto, independentemente de decisão judicial. Após 15 dias contados do vencimento da 3.ª parcela, não tendo havido o adimplemento, Paula notificou José para desocupar o imóvel no prazo estabelecido na cláusula expressa no contrato. Nessa situação hipotética, conforme disposto no Código Civil, José A deverá desocupar o imóvel no prazo estabelecido no contrato, em decorrência da cláusula resolutiva expressa nesse sentido, sob pena de ser processado por ação de reintegração de posse. B não poderá ser obrigado a desocupar o imóvel, sendo a execução do contrato pela via da ação de cobrança a única opção para Paula. C poderá recusar-se a desocupar o imóvel, porquanto abusiva a cláusula contratual prevista nesse sentido, devendo Paula ajuizar ação para a resolução contratual. D poderá recusar-se a desocupar o imóvel, pois a cláusula resolutiva do contrato, ainda que legal, não pode ser executada sem intervenção judicial. E deverá desocupar o imóvel no prazo estabelecido no contrato, uma vez que a resolução do contrato constitui efeito automático do inadimplemento.$q$,$q$Paula celebrou com José contrato de compra e venda de um ponto comercial na Praia do Morro, em Guarapari – ES. No contrato, ficou estabelecido que José pagaria o preço combinado em dez parcelas iguais e a ele seria transferida a posse após o pagamento da 1.ª parcela. Ainda, havia cláusula resolutiva expressa no sentido de que, em caso de inadimplemento, Paula retomaria a posse do ponto, independentemente de decisão judicial. Após 15 dias contados do vencimento da 3.ª parcela, não tendo havido o adimplemento, Paula notificou José para desocupar o imóvel no prazo estabelecido na cláusula expressa no contrato. Nessa situação hipotética, conforme disposto no Código Civil, José A deverá desocupar o imóvel no prazo estabelecido no contrato, em decorrência da cláusula resolutiva expressa nesse sentido, sob pena de ser processado por ação de reintegração de posse. B não poderá ser obrigado a desocupar o imóvel, sendo a execução do contrato pela via da ação de cobrança a única opção para Paula. C poderá recusar-se a desocupar o imóvel, porquanto abusiva a cláusula contratual prevista nesse sentido, devendo Paula ajuizar ação para a resolução contratual. D poderá recusar-se a desocupar o imóvel, pois a cláusula resolutiva do contrato, ainda que legal, não pode ser executada sem intervenção judicial. E deverá desocupar o imóvel no prazo estabelecido no contrato, uma vez que a resolução do contrato constitui efeito automático do inadimplemento.$q$,'X',2,'annulled',true,false,$q$Item anulado no gabarito oficial definitivo (729_PC_ES_DELEGADO_GABARITOS); não é exibido aos estudantes.$q$),
(2022,61,$q$Direito Civil$q$,$q$De acordo com as disposições do Código Civil, é nulo o negócio jurídico A firmado por agente relativamente incapaz na data da celebração. B que seja resultado de simulação. C quando uma parte, em estado de perigo, se comprometer a cumprir prestação excessiva. D celebrado com lesão a uma das partes, obrigando-a a dever manifestamente desproporcional ao valor da prestação oposta. E celebrado com engano (dolo) provocado por uma das partes.$q$,$q$De acordo com as disposições do Código Civil, é nulo o negócio jurídico A firmado por agente relativamente incapaz na data da celebração. B que seja resultado de simulação. C quando uma parte, em estado de perigo, se comprometer a cumprir prestação excessiva. D celebrado com lesão a uma das partes, obrigando-a a dever manifestamente desproporcional ao valor da prestação oposta. E celebrado com engano (dolo) provocado por uma das partes.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,62,$q$Direito Civil$q$,$q$Gilvan e Mariana mantinham relacionamento amoroso havia seis anos, quando Mariana engravidou. O casal contou aos familiares e amigos que a criança que estava a caminho era um menino e se chamaria Cauã. No entanto, às vésperas do nascimento do filho, Gilvan rompeu o relacionamento após ter descoberto que, havia três meses, Mariana mantinha outro relacionamento amoroso. Nascida a criança, Gilvan registrou-a com o nome de Enzo Cauã, em homenagem ao seu avô, sem consultar Mariana. Nessa situação hipotética, em consonância com o entendimento do Superior Tribunal de Justiça, Mariana A poderia requerer a supressão do prenome Enzo ainda que não tivesse combinado um nome previamente com Gilvan. B não poderá requerer a alteração do nome de seu filho, em razão da imutabilidade do nome. C poderá requerer, perante o cartório de registro civil, a exclusão do prenome Enzo, sob o argumento de que Gilvan violou o dever de lealdade familiar e a boa-fé objetiva. D deverá requerer em juízo a exclusão do prenome Enzo e comprovar que Gilvan violou o dever de lealdade familiar e a boa-fé objetiva. E poderá requerer em juízo a supressão do prenome Enzo desde que comprove o intuito de vingança de Gilvan.$q$,$q$Gilvan e Mariana mantinham relacionamento amoroso havia seis anos, quando Mariana engravidou. O casal contou aos familiares e amigos que a criança que estava a caminho era um menino e se chamaria Cauã. No entanto, às vésperas do nascimento do filho, Gilvan rompeu o relacionamento após ter descoberto que, havia três meses, Mariana mantinha outro relacionamento amoroso. Nascida a criança, Gilvan registrou-a com o nome de Enzo Cauã, em homenagem ao seu avô, sem consultar Mariana. Nessa situação hipotética, em consonância com o entendimento do Superior Tribunal de Justiça, Mariana A poderia requerer a supressão do prenome Enzo ainda que não tivesse combinado um nome previamente com Gilvan. B não poderá requerer a alteração do nome de seu filho, em razão da imutabilidade do nome. C poderá requerer, perante o cartório de registro civil, a exclusão do prenome Enzo, sob o argumento de que Gilvan violou o dever de lealdade familiar e a boa-fé objetiva. D deverá requerer em juízo a exclusão do prenome Enzo e comprovar que Gilvan violou o dever de lealdade familiar e a boa-fé objetiva. E poderá requerer em juízo a supressão do prenome Enzo desde que comprove o intuito de vingança de Gilvan.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,63,$q$Medicina Legal$q$,$q$O desenvolvimento tecnológico e social, associado à contribuição de diversas ciências, tem propiciado a evolução da medicina legal no sentido de sua subespecialização. Em relação aos ramos da medicina legal, assinale a opção correta. A A criminalística estuda os diversos aspectos da natureza do crime, do criminoso, da vítima e do ambiente. B A tanatologia forense estuda o autor do crime, principalmente quanto ao seu comportamento em relação à vítima no momento da ocorrência do delito. C A policiologia científica estuda os métodos científicos utilizados pela medicina legal no auxílio das investigações policiais. D A infortunística investiga, de forma técnica, os infortúnios que ocorreram com a vítima, avaliando os indícios materiais do crime, seu valor e sua interpretação nos elementos constitutivos do corpo de delito. E A vitimologia forense estuda a morte e o morto, bem como suas repercussões na esfera jurídico-social.$q$,$q$O desenvolvimento tecnológico e social, associado à contribuição de diversas ciências, tem propiciado a evolução da medicina legal no sentido de sua subespecialização. Em relação aos ramos da medicina legal, assinale a opção correta. A A criminalística estuda os diversos aspectos da natureza do crime, do criminoso, da vítima e do ambiente. B A tanatologia forense estuda o autor do crime, principalmente quanto ao seu comportamento em relação à vítima no momento da ocorrência do delito. C A policiologia científica estuda os métodos científicos utilizados pela medicina legal no auxílio das investigações policiais. D A infortunística investiga, de forma técnica, os infortúnios que ocorreram com a vítima, avaliando os indícios materiais do crime, seu valor e sua interpretação nos elementos constitutivos do corpo de delito. E A vitimologia forense estuda a morte e o morto, bem como suas repercussões na esfera jurídico-social.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,64,$q$Medicina Legal$q$,$q$No que diz respeito ao corpo de delito e à perícia em medicina legal, assinale a opção correta. A Quando o suspeito confessar o crime, será desnecessário o exame de corpo de delito, seja direto, seja indireto. B Os vestígios de crimes que ensejam a necessidade de exame de corpo de delito devem ser analisados conforme sua ordem de entrada no sistema, configurando crime qualquer alteração nessa ordem. C O juiz não poderá determinar a produção de prova técnica simplificada em substituição à perícia, mesmo que o ponto controvertido seja de menor complexidade. D O juiz tem a obrigação de determinar a emissão de laudo pericial quando for necessário conhecimento científico ou técnico para provar um fato. E O juiz deverá indeferir uma perícia quando a prova do fato não depender de conhecimento especial de técnico.$q$,$q$No que diz respeito ao corpo de delito e à perícia em medicina legal, assinale a opção correta. A Quando o suspeito confessar o crime, será desnecessário o exame de corpo de delito, seja direto, seja indireto. B Os vestígios de crimes que ensejam a necessidade de exame de corpo de delito devem ser analisados conforme sua ordem de entrada no sistema, configurando crime qualquer alteração nessa ordem. C O juiz não poderá determinar a produção de prova técnica simplificada em substituição à perícia, mesmo que o ponto controvertido seja de menor complexidade. D O juiz tem a obrigação de determinar a emissão de laudo pericial quando for necessário conhecimento científico ou técnico para provar um fato. E O juiz deverá indeferir uma perícia quando a prova do fato não depender de conhecimento especial de técnico.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,65,$q$Medicina Legal$q$,$q$Acerca dos documentos médico-legais, assinale a opção correta. A Toda notificação compulsória médica deve ser comunicada à autoridade competente no prazo de até 24 h, conforme norma do Ministério da Saúde. B O preâmbulo de um relatório pericial deve conter o registro dos fatos mais importantes que deram origem à requisição da perícia pela autoridade e que podem esclarecer e orientar a ação do perito. C Chama-se de auto o relatório que é ditado diretamente ao escrivão e diante de testemunhas. D O atestado médico administrativo é utilizado para um aluno justificar sua ausência a uma atividade escolar. E O atestado médico é um documento que necessita da formalidade sobre compromisso legal, devendo ser fornecido por médico que esteja no exercício regular da medicina.$q$,$q$Acerca dos documentos médico-legais, assinale a opção correta. A Toda notificação compulsória médica deve ser comunicada à autoridade competente no prazo de até 24 h, conforme norma do Ministério da Saúde. B O preâmbulo de um relatório pericial deve conter o registro dos fatos mais importantes que deram origem à requisição da perícia pela autoridade e que podem esclarecer e orientar a ação do perito. C Chama-se de auto o relatório que é ditado diretamente ao escrivão e diante de testemunhas. D O atestado médico administrativo é utilizado para um aluno justificar sua ausência a uma atividade escolar. E O atestado médico é um documento que necessita da formalidade sobre compromisso legal, devendo ser fornecido por médico que esteja no exercício regular da medicina.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,66,$q$Medicina Legal$q$,$q$Assinale a opção correta acerca do processo de identificação e averiguação da identidade de um indivíduo, importante para a caracterização das pessoas na sociedade, além de constituir um instrumento de controle do fluxo de pessoas entre países. A No processo de identificação, podem-se usar dados do perfil genético da pessoa, que, depois de coletados, são armazenados em banco de dados de perfis genéticos gerenciado pelo delegado-chefe da delegacia regional de cada estado. B Para caracterizar uma ossada como humana, podem ser observados os canais de Havers, os quais se apresentam elípticos, mais largos e em menor número nos humanos que nos animais. C Conclui-se que uma ossada é masculina caso os ossos pélvicos apresentem rugas ósseas de inserção muscular pouco pronunciadas e suas dimensões horizontais sejam maiores que as verticais. D Os denominados pontos craniométricos não devem ser usados para caracterizar a forma do crânio humano, pois podem ocasionar erros na identificação. E No processo de identificação humana em local de morte violenta, inicialmente usa-se o luminol, que reage exclusivamente com o sangue humano.$q$,$q$Assinale a opção correta acerca do processo de identificação e averiguação da identidade de um indivíduo, importante para a caracterização das pessoas na sociedade, além de constituir um instrumento de controle do fluxo de pessoas entre países. A No processo de identificação, podem-se usar dados do perfil genético da pessoa, que, depois de coletados, são armazenados em banco de dados de perfis genéticos gerenciado pelo delegado-chefe da delegacia regional de cada estado. B Para caracterizar uma ossada como humana, podem ser observados os canais de Havers, os quais se apresentam elípticos, mais largos e em menor número nos humanos que nos animais. C Conclui-se que uma ossada é masculina caso os ossos pélvicos apresentem rugas ósseas de inserção muscular pouco pronunciadas e suas dimensões horizontais sejam maiores que as verticais. D Os denominados pontos craniométricos não devem ser usados para caracterizar a forma do crânio humano, pois podem ocasionar erros na identificação. E No processo de identificação humana em local de morte violenta, inicialmente usa-se o luminol, que reage exclusivamente com o sangue humano.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,67,$q$Medicina Legal$q$,$q$Considerando o uso de dados antropométricos e antropológicos para determinar a identidade civil de uma pessoa no âmbito da identificação judiciária, assinale a opção correta. A A presilha interna é caracterizada pela presença de dois deltas à direita do observador e de dois núcleos voltados à esquerda. B No sistema datiloscópico de Vucetich, o delta é a característica fundamental, sendo o encontro das linhas marginais com as basais, limitado internamente pelas linhas nucleares. C O arco é caracterizado pelo encontro dos sistemas basilares e marginais com dois deltas. D O verticilo é caracterizado pelo encontro de três deltas. E A presilha externa é caracterizada pela presença de dois deltas à direita do observador e de um núcleo voltado à direita, mas em sentido contrário aos deltas.$q$,$q$Considerando o uso de dados antropométricos e antropológicos para determinar a identidade civil de uma pessoa no âmbito da identificação judiciária, assinale a opção correta. A A presilha interna é caracterizada pela presença de dois deltas à direita do observador e de dois núcleos voltados à esquerda. B No sistema datiloscópico de Vucetich, o delta é a característica fundamental, sendo o encontro das linhas marginais com as basais, limitado internamente pelas linhas nucleares. C O arco é caracterizado pelo encontro dos sistemas basilares e marginais com dois deltas. D O verticilo é caracterizado pelo encontro de três deltas. E A presilha externa é caracterizada pela presença de dois deltas à direita do observador e de um núcleo voltado à direita, mas em sentido contrário aos deltas.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,68,$q$Medicina Legal$q$,$q$Lesões produzidas por projéteis de arma de fogo podem ser classificadas em função da energia do projétil, de sua massa e do tipo de lesão tecidual. Acerca de aspectos relativos a essa temática, assinale a opção correta. A A velocidade é o vetor que apresenta menos influência no resultado da energia cinética de um projétil. B O fenômeno da cavitação nas lesões de entrada de projétil de arma de fogo se caracteriza por ser sempre permanente, o que se deve ao fato de o projétil transferir energia cinética para o alvo. C Em geral, o projétil de alta energia tem velocidade inicial acima de 600 m/s. D Em geral, a velocidade inicial do projétil de baixa energia é de até 200 m/s. E Em geral, a velocidade inicial do projétil de média energia fica entre 200 m/s e 600 m/s.$q$,$q$Lesões produzidas por projéteis de arma de fogo podem ser classificadas em função da energia do projétil, de sua massa e do tipo de lesão tecidual. Acerca de aspectos relativos a essa temática, assinale a opção correta. A A velocidade é o vetor que apresenta menos influência no resultado da energia cinética de um projétil. B O fenômeno da cavitação nas lesões de entrada de projétil de arma de fogo se caracteriza por ser sempre permanente, o que se deve ao fato de o projétil transferir energia cinética para o alvo. C Em geral, o projétil de alta energia tem velocidade inicial acima de 600 m/s. D Em geral, a velocidade inicial do projétil de baixa energia é de até 200 m/s. E Em geral, a velocidade inicial do projétil de média energia fica entre 200 m/s e 600 m/s.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,69,$q$Criminologia$q$,$q$A primeira teoria sociológica que fixou o entendimento de que o crime é produto da desorganização própria da grande cidade, onde se debilita o controle social e se deterioram as relações humanas, foi a A ecológica. B estrutural-funcionalista. C da anomia. D conflitual marxista. E do conflito social.$q$,$q$A primeira teoria sociológica que fixou o entendimento de que o crime é produto da desorganização própria da grande cidade, onde se debilita o controle social e se deterioram as relações humanas, foi a A ecológica. B estrutural-funcionalista. C da anomia. D conflitual marxista. E do conflito social.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,70,$q$Criminologia$q$,$q$Constitui exemplo de programa de prevenção primária aquele que busca A a melhoria do bem-estar social. B a prevenção policial. C o controle dos meios de comunicação. D a reabilitação do condenado. E a ordenação urbana.$q$,$q$Constitui exemplo de programa de prevenção primária aquele que busca A a melhoria do bem-estar social. B a prevenção policial. C o controle dos meios de comunicação. D a reabilitação do condenado. E a ordenação urbana.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,71,$q$Criminologia$q$,$q$A interdisciplinaridade é intrínseca à natureza da criminologia. Dessa forma, a ciência que se afasta do estudo da criminologia é a A biologia. B hermenêutica dogmática. C psicologia. D estatística. E sociologia.$q$,$q$A interdisciplinaridade é intrínseca à natureza da criminologia. Dessa forma, a ciência que se afasta do estudo da criminologia é a A biologia. B hermenêutica dogmática. C psicologia. D estatística. E sociologia.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,72,$q$Criminologia$q$,$q$Na criminologia, a concepção do delinquente como um ser inferior, que é incapaz de dirigir por si mesmo a própria vida e cuja vontade requer uma eficaz e desinteressada intervenção tutelar do Estado, é típica da visão A clássica. B positivista. C correcionalista. D pluralista. E marxista.$q$,$q$Na criminologia, a concepção do delinquente como um ser inferior, que é incapaz de dirigir por si mesmo a própria vida e cuja vontade requer uma eficaz e desinteressada intervenção tutelar do Estado, é típica da visão A clássica. B positivista. C correcionalista. D pluralista. E marxista.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,73,$q$Criminologia$q$,$q$A criminologia consiste em uma ciência A exata. B puramente academicista. C prática. D de dados. E que atua como uma central de informações sobre o delito.$q$,$q$A criminologia consiste em uma ciência A exata. B puramente academicista. C prática. D de dados. E que atua como uma central de informações sobre o delito.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,74,$q$Criminologia$q$,$q$A função básica da criminologia consiste em A informar a sociedade e o poder público sobre o delinquente, a vítima e o delito, reunindo-se elementos para compreender o problema criminal, preveni-lo e intervir positivamente no delinquente. B ter um saber absoluto, certo e definitivo sobre o problema criminal existente dentro da sociedade. C servir de inspiração para a edição de atos normativos pelo poder público. D formar um banco de dados centralizado, a fim de auxiliar o poder público nas suas decisões. E explicar o fenômeno científico tal qual uma ciência exata, a partir da formulação de leis universais e de relações de causa e efeito.$q$,$q$A função básica da criminologia consiste em A informar a sociedade e o poder público sobre o delinquente, a vítima e o delito, reunindo-se elementos para compreender o problema criminal, preveni-lo e intervir positivamente no delinquente. B ter um saber absoluto, certo e definitivo sobre o problema criminal existente dentro da sociedade. C servir de inspiração para a edição de atos normativos pelo poder público. D formar um banco de dados centralizado, a fim de auxiliar o poder público nas suas decisões. E explicar o fenômeno científico tal qual uma ciência exata, a partir da formulação de leis universais e de relações de causa e efeito.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,75,$q$Criminologia$q$,$q$Está fora do âmbito de proteção da Lei n.º 11.340/2006, que trata da violência doméstica contra a mulher, A a filha transexual que é ameaçada pelo pai dentro da própria residência. B a mãe vulnerável que é ameaçada e agredida pela própria filha com a qual convive. C a mulher agredida dentro do ambiente laboral por colega de trabalho do sexo masculino com quem nunca teve relação íntima ou de afeto. D a empregada doméstica agredida pelo neto da empregadora dentro da casa desta. E a mulher vítima de contravenção penal em razão do gênero.$q$,$q$Está fora do âmbito de proteção da Lei n.º 11.340/2006, que trata da violência doméstica contra a mulher, A a filha transexual que é ameaçada pelo pai dentro da própria residência. B a mãe vulnerável que é ameaçada e agredida pela própria filha com a qual convive. C a mulher agredida dentro do ambiente laboral por colega de trabalho do sexo masculino com quem nunca teve relação íntima ou de afeto. D a empregada doméstica agredida pelo neto da empregadora dentro da casa desta. E a mulher vítima de contravenção penal em razão do gênero.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,76,$q$Legislação Penal Especial$q$,$q$Após investigação de local em que, supostamente, se armazenavam, organizavam e vendiam drogas de forma contínua, foi expedido e cumprido mandado de busca e apreensão, a partir do qual a autoridade policial encontrou, dentro de uma residência, dez indivíduos portando uma quantidade elevada de drogas, bem como três balanças de precisão, que serviam para o preparo de drogas ilícitas. Nessa situação hipotética, conforme o entendimento do Superior Tribunal de Justiça, se os referidos indivíduos forem indiciados, eles deverão responder por A tráfico de drogas e associação para o tráfico. B tráfico de drogas em concurso, com posse de maquinário para preparação de droga, e associação para o tráfico. C associação para o tráfico em concurso, com posse de maquinário para preparação de droga. D tráfico de drogas e posse de maquinário para preparação de droga. E tráfico de drogas somente.$q$,$q$Após investigação de local em que, supostamente, se armazenavam, organizavam e vendiam drogas de forma contínua, foi expedido e cumprido mandado de busca e apreensão, a partir do qual a autoridade policial encontrou, dentro de uma residência, dez indivíduos portando uma quantidade elevada de drogas, bem como três balanças de precisão, que serviam para o preparo de drogas ilícitas. Nessa situação hipotética, conforme o entendimento do Superior Tribunal de Justiça, se os referidos indivíduos forem indiciados, eles deverão responder por A tráfico de drogas e associação para o tráfico. B tráfico de drogas em concurso, com posse de maquinário para preparação de droga, e associação para o tráfico. C associação para o tráfico em concurso, com posse de maquinário para preparação de droga. D tráfico de drogas e posse de maquinário para preparação de droga. E tráfico de drogas somente.$q$,'A',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,77,$q$Legislação Penal Especial$q$,$q$No Estatuto do Desarmamento, considera-se crime hediondo A o porte ilegal de arma de fogo de uso permitido. B ter em depósito arma de fogo de uso permitido. C o porte ilegal de arma de fogo, em qualquer modalidade. D o crime de disparo de arma de fogo. E a posse ilegal de arma de fogo de uso proibido.$q$,$q$No Estatuto do Desarmamento, considera-se crime hediondo A o porte ilegal de arma de fogo de uso permitido. B ter em depósito arma de fogo de uso permitido. C o porte ilegal de arma de fogo, em qualquer modalidade. D o crime de disparo de arma de fogo. E a posse ilegal de arma de fogo de uso proibido.$q$,'E',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,78,$q$Legislação Penal Especial$q$,$q$Configura crime de abuso de autoridade A submeter o preso a interrogatório durante o repouso noturno, mesmo que ele tenha sido capturado em flagrante delito. B invadir clandestinamente imóvel alheio, sem determinação judicial, ainda que fundados indícios indiquem a necessidade do ingresso em razão de situação de flagrante delito. C submeter a vítima de infração penal a procedimento desnecessário que a leve a reviver situação estigmatizante. D obrigar o preso a passar pelo procedimento de reconhecimento pessoal. E requisitar instauração de investigação preliminar sumária, ainda que justificada, de infração penal em desfavor de alguém, quando não houver indício da prática de crime, de ilícito funcional ou de infração administrativa.$q$,$q$Configura crime de abuso de autoridade A submeter o preso a interrogatório durante o repouso noturno, mesmo que ele tenha sido capturado em flagrante delito. B invadir clandestinamente imóvel alheio, sem determinação judicial, ainda que fundados indícios indiquem a necessidade do ingresso em razão de situação de flagrante delito. C submeter a vítima de infração penal a procedimento desnecessário que a leve a reviver situação estigmatizante. D obrigar o preso a passar pelo procedimento de reconhecimento pessoal. E requisitar instauração de investigação preliminar sumária, ainda que justificada, de infração penal em desfavor de alguém, quando não houver indício da prática de crime, de ilícito funcional ou de infração administrativa.$q$,'C',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,79,$q$Legislação Penal Especial$q$,$q$Em relação ao crime de lavagem de dinheiro, assinale a opção correta. A A caracterização desse crime depende da comprovação do crime antecedente. B A modalidade de ocultar a propriedade de bens provenientes diretamente de infração penal é conduta de natureza permanente, até que os objetos materiais da lavagem se tornem conhecidos. C A autolavagem não é punível. D É imprescindível que o autor da lavagem de dinheiro seja também o autor do crime antecedente. E A lavagem de dinheiro só persiste se o crime antecedente for um dos arrolados na Lei n.º 9.613/1998.$q$,$q$Em relação ao crime de lavagem de dinheiro, assinale a opção correta. A A caracterização desse crime depende da comprovação do crime antecedente. B A modalidade de ocultar a propriedade de bens provenientes diretamente de infração penal é conduta de natureza permanente, até que os objetos materiais da lavagem se tornem conhecidos. C A autolavagem não é punível. D É imprescindível que o autor da lavagem de dinheiro seja também o autor do crime antecedente. E A lavagem de dinheiro só persiste se o crime antecedente for um dos arrolados na Lei n.º 9.613/1998.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$),
(2022,80,$q$Legislação Penal Especial$q$,$q$A posse de vídeo que contém cena de sexo explícito envolvendo adolescente é A conduta atípica. B crime previsto no Estatuto da Criança e do Adolescente. C crime previsto no Código Penal. D crime apenas se o vídeo houver sido obtido pela Internet ou por outro sistema de informática ou telemático. E crime apenas se houver relação de parentesco entre o possuidor do vídeo e o adolescente que aparece na referida cena.$q$,$q$A posse de vídeo que contém cena de sexo explícito envolvendo adolescente é A conduta atípica. B crime previsto no Estatuto da Criança e do Adolescente. C crime previsto no Código Penal. D crime apenas se o vídeo houver sido obtido pela Internet ou por outro sistema de informática ou telemático. E crime apenas se houver relação de parentesco entre o possuidor do vídeo e o adolescente que aparece na referida cena.$q$,'B',2,'under_review',true,false,$q$Transcrição verbatim do caderno de provas Polícia Civil do Espírito Santo (PCES) - Delegado de Polícia - 2022, Edital nº 1 – PCES, de 4 de julho de 2022, banca CEBRASPE (aplicação 11/9/2022). Gabarito conferido no Gabarito Oficial Definitivo (729_PC_ES_DELEGADO_GABARITOS). Base legal ainda não conferida individualmente no planalto.gov.br — aguardando revisão item a item antes de content_status=active.$q$)), editions as (
  select id,contest_year from public.syllabus_editions
  where contest_name='Polícia Civil do Estado do Espírito Santo' and role_name='Delegado de Polícia' and contest_year=2022
), resolved as (
  select imported.*, question_source.id question_source_id, answer_source.id answer_key_source_id, topic.id syllabus_topic_id
  from imported
  join editions on editions.contest_year=imported.exam_year
  join public.syllabus_topics topic on topic.edition_id=editions.id and topic.discipline=imported.subject and topic.topic_order=1
  join public.content_sources question_source on question_source.title=(case when imported.item_number<=20 then 'Prova objetiva PC/ES - Delegado de Polícia - 2022' else 'Prova objetiva PC/ES - Delegado de Polícia - 2022 (Conhecimentos Específicos)' end)
  join public.content_sources answer_source on answer_source.title=(case when imported.item_number<=20 then 'Gabarito definitivo PC/ES - Delegado de Polícia - 2022 (Conhecimentos Gerais)' else 'Gabarito definitivo PC/ES - Delegado de Polícia - 2022 (Conhecimentos Específicos)' end)
)
insert into public.official_exam_questions (
  question_source_id,answer_key_source_id,syllabus_topic_id,contest_name,career_name,exam_board,exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
)
select question_source_id,answer_key_source_id,syllabus_topic_id,'Polícia Civil do Estado do Espírito Santo','Delegado de Polícia','CEBRASPE',exam_year,item_number,subject,
  question_text,raw_extraction,official_answer,source_page,content_status,legal_review_required,
  context_review_required,review_note
from resolved
on conflict (contest_name,career_name,exam_year,item_number) do nothing;
